M.add({
  id: "tawhid", level: 2, title: "كتاب التوحيد",
  fullTitle: "كتاب التوحيد الذي هو حق الله على العبيد",
  author: "الإمام المجدد محمد بن عبد الوهاب التميمي", died: "١٢٠٦هـ",
  pages: "١٦٣–٤٢٠", note: "الأبواب وأدلتها دون المسائل",
  lessons: [
    { title: "[١] كتاب التوحيد", paras: [
      "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ",
      "#كِتَابُ التَّوْحِيدِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَمَا خَلَقْتُ الْجِنَّ وَالإِنْسَ إِلَّا لِيَعْبُدُونِ﴾.",
      "وَقَوْلُهُ: ﴿وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولاً أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ﴾ الآيَةَ.",
      "وَقَوْلُهُ تَعَالَى: ﴿قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا بِهِ شَيْئاً﴾ إِلَى قَوْلِهِ: ﴿وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيماً فَاتَّبِعُوهُ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَاناً﴾ الآيَةَ.",
      "وَقَوْلُهُ تَعَالَى: ﴿وَاعْبُدُوا اللَّهَ وَلَا تُشْرِكُوا بِهِ شَيْئاً وَبِالْوَالِدَيْنِ إِحْسَاناً﴾ الآيَةَ.",
      "قَالَ ابْنُ مَسْعُودٍ رضي الله عنه: «مَنْ أَرَادَ أَنْ يَنْظُرَ إِلَى وَصِيَّةِ مُحَمَّدٍ ﷺ الَّتِي عَلَيْهَا خَاتَمُهُ؛ فَلْيَقْرَأْ: ﴿قُلْ تَعَالَوْا أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ أَلَّا تُشْرِكُوا بِهِ شَيْئاً﴾ إِلَى قَوْلِهِ: ﴿وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيماً فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ﴾ الآيَةَ».",
      "وَعَنْ مُعَاذِ بْنِ جَبَلٍ رضي الله عنه قَالَ: «كُنْتُ رَدِيفَ النَّبِيِّ ﷺ عَلَى حِمَارٍ، فَقَالَ: يَا مُعَاذُ! أَتَدْرِي مَا حَقُّ اللَّهِ عَلَى الْعِبَادِ، وَمَا حَقُّ الْعِبَادِ عَلَى اللَّهِ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ.",
      "قَالَ: فَإِنَّ حَقَّ اللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئاً، وَحَقَّ الْعِبَادِ عَلَى اللَّهِ أَلَّا يُعَذِّبَ مَنْ لَا يُشْرِكُ بِهِ شَيْئاً.",
      "فَقُلْتُ: يَا رَسُولَ اللَّهِ! أَفَلَا أُبَشِّرُ النَّاسَ؟ قَالَ: لَا تُبَشِّرْهُمْ فَيَتَّكِلُوا» أَخْرَجَاهُ فِي الصَّحِيحَيْنِ."
    ]},
    { title: "[٢] باب فضل التوحيد وما يكفر من الذنوب", paras: [
      "#بَابُ فَضْلِ التَّوْحِيدِ، وَمَا يُكَفِّرُ مِنَ الذُّنُوبِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ أُولَئِكَ لَهُمُ الأَمْنُ وَهُمْ مُهْتَدُونَ﴾.",
      "عَنْ عُبَادَةَ بْنِ الصَّامِتِ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنْ شَهِدَ أَلَّا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، وَأَنَّ عِيسَى عَبْدُ اللَّهِ وَرَسُولُهُ، وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، وَالْجَنَّةَ حَقٌّ، وَالنَّارَ حَقٌّ؛ أَدْخَلَهُ اللَّهُ الْجَنَّةَ عَلَى مَا كَانَ مِنَ الْعَمَلِ» أَخْرَجَاهُ.",
      "وَلَهُمَا فِي حَدِيثِ عِتْبَانَ رضي الله عنه: «فَإِنَّ اللَّهَ حَرَّمَ عَلَى النَّارِ مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ؛ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ».",
      "وَعَنْ أَبِي سَعِيدٍ رضي الله عنه مَرْفُوعاً: «قَالَ مُوسَى: يَا رَبِّ! عَلِّمْنِي شَيْئاً أَذْكُرُكَ وَأَدْعُوكَ بِهِ؟ قَالَ: قُلْ يَا مُوسَى: لَا إِلَهَ إِلَّا اللَّهُ.",
      "قَالَ: يَا رَبِّ! كُلُّ عِبَادِكَ يَقُولُونَ هَذَا، قَالَ: يَا مُوسَى! لَوْ أَنَّ السَّمَاوَاتِ السَّبْعَ وَعَامِرَهُنَّ غَيْرِي وَالأَرَضِينَ السَّبْعَ فِي كِفَّةٍ، وَلَا إِلَهَ إِلَّا اللَّهُ فِي كِفَّةٍ، مَالَتْ بِهِنَّ لَا إِلَهَ إِلَّا اللَّهُ» رَوَاهُ ابْنُ حِبَّانَ، وَالْحَاكِمُ وَصَحَّحَهُ.",
      "وَلِلتِّرْمِذِيِّ وَحَسَّنَهُ: عَنْ أَنَسٍ رضي الله عنه قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «قَالَ اللَّهُ تَعَالَى: يَا ابْنَ آدَمَ! إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الأَرْضِ خَطَايَا، ثُمَّ لَقِيتَنِي لَا تُشْرِكُ بِي شَيْئاً؛ لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً»."
    ]},
    { title: "[٣] باب من حقق التوحيد دخل الجنة بغير حساب", paras: [
      "#بَابُ مَنْ حَقَّقَ التَّوْحِيدَ؛ دَخَلَ الْجَنَّةَ بِغَيْرِ حِسَابٍ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿إِنَّ إِبْرَاهِيمَ كَانَ أُمَّةً قَانِتاً لِلَّهِ حَنِيفاً وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ﴾.",
      "وَقَالَ: ﴿وَالَّذِينَ هُمْ بِرَبِّهِمْ لَا يُشْرِكُونَ﴾.",
      "عَنْ حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ قَالَ: «كُنْتُ عِنْدَ سَعِيدِ بْنِ جُبَيْرٍ، فَقَالَ: أَيُّكُمْ رَأَى الْكَوْكَبَ الَّذِي انْقَضَّ الْبَارِحَةَ؟ قُلْتُ: أَنَا.",
      "ثُمَّ قُلْتُ: أَمَا إِنِّي لَمْ أَكُنْ فِي صَلَاةٍ، وَلَكِنِّي لُدِغْتُ، قَالَ: فَمَا صَنَعْتَ؟ قُلْتُ: ارْتَقَيْتُ، قَالَ: فَمَا حَمَلَكَ عَلَى ذَلِكَ؟ قُلْتُ: حَدِيثٌ حَدَّثَنَاهُ الشَّعْبِيُّ، قَالَ: وَمَا حَدَّثَكُمْ؟ قُلْتُ: حَدَّثَنَا عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ رضي الله عنه أَنَّهُ قَالَ: لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ، أَوْ حُمَةٍ، فَقَالَ: قَدْ أَحْسَنَ مَنِ انْتَهَى إِلَى مَا سَمِعَ.",
      "وَلَكِنْ حَدَّثَنَا ابْنُ عَبَّاسٍ رضي الله عنهما عَنِ النَّبِيِّ ﷺ قَالَ: عُرِضَتْ عَلَيَّ الأُمَمُ، فَرَأَيْتُ النَّبِيَّ وَمَعَهُ الرَّهْطُ، وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ، وَالنَّبِيَّ لَيْسَ مَعَهُ أَحَدٌ.",
      "إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ، فَظَنَنْتُ أَنَّهُمْ أُمَّتِي، فَقِيلَ لِي: هَذَا مُوسَى وَقَوْمُهُ.",
      "فَنَظَرْتُ فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: هَذِهِ أُمَّتُكَ، وَمَعَهُمْ سَبْعُونَ أَلْفاً يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ.",
      "ثُمَّ نَهَضَ، فَدَخَلَ مَنْزِلَهُ، فَخَاضَ النَّاسُ فِي أُولَئِكَ، فَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ صَحِبُوا رَسُولَ اللَّهِ ﷺ.",
      "وَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ وُلِدُوا فِي الإِسْلَامِ وَلَمْ يُشْرِكُوا بِاللَّهِ شَيْئاً - وَذَكَرُوا أَشْيَاءَ -.",
      "فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ ﷺ فَأَخْبَرُوهُ، فَقَالَ: هُمُ الَّذِينَ لَا يَسْتَرْقُونَ، وَلَا يَكْتَوُونَ، وَلَا يَتَطَيَّرُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ.",
      "فَقَامَ عُكَّاشَةُ بْنُ مِحْصَنٍ، فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: أَنْتَ مِنْهُمْ.",
      "ثُمَّ قَامَ رَجُلٌ آخَرُ، فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ»."
    ]},
    { title: "[٤] باب الخوف من الشرك", paras: [
      "#بَابُ الْخَوْفِ مِنَ الشِّرْكِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ﴾.",
      "وَقَالَ الْخَلِيلُ عَلَيْهِ السَّلَامُ: ﴿وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الأَصْنَامَ﴾.",
      "وَفِي الْحَدِيثِ: «أَخْوَفُ مَا أَخَافُ عَلَيْكُمُ: الشِّرْكُ الأَصْغَرُ، فَسُئِلَ عَنْهُ؟ فَقَالَ: الرِّيَاءُ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ مَاتَ وَهُوَ يَدْعُو لِلَّهِ نِدّاً؛ دَخَلَ النَّارَ» رَوَاهُ الْبُخَارِيُّ.",
      "وَلِمُسْلِمٍ: عَنْ جَابِرٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئاً دَخَلَ الْجَنَّةَ، وَمَنْ لَقِيَهُ يُشْرِكُ بِهِ شَيْئاً دَخَلَ النَّارَ»."
    ]},
    { title: "[٥] باب الدعاء إلى شهادة أن لا إله إلا الله", paras: [
      "#بَابُ الدُّعَاءِ إِلَى شَهَادَةِ أَلَّا إِلَهَ إِلَّا اللَّهُ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ عَلَى بَصِيرَةٍ أَنَا وَمَنِ اتَّبَعَنِي﴾.",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما أَنَّ رَسُولَ اللَّهِ ﷺ لَمَّا بَعَثَ مُعَاذاً إِلَى الْيَمَنِ قَالَ لَهُ: «إِنَّكَ تَأْتِي قَوْماً مِنْ أَهْلِ الْكِتَابِ؛ فَلْيَكُنْ أَوَّلَ مَا تَدْعُوهُمْ إِلَيْهِ: شَهَادَةُ أَلَّا إِلَهَ إِلَّا اللَّهُ - وَفِي رِوَايَةٍ: إِلَى أَنْ يُوَحِّدُوا اللَّهَ -.",
      "فَإِنْ هُمْ أَطَاعُوكَ لِذَلِكَ؛ فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ.",
      "فَإِنْ هُمْ أَطَاعُوكَ لِذَلِكَ؛ فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ.",
      "فَإِنْ هُمْ أَطَاعُوكَ لِذَلِكَ؛ فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ، وَاتَّقِ دَعْوَةَ الْمَظْلُومِ؛ فَإِنَّهُ لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ» أَخْرَجَاهُ.",
      "وَلَهُمَا: عَنْ سَهْلِ بْنِ سَعْدٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ يَوْمَ خَيْبَرَ: «لَأُعْطِيَنَّ الرَّايَةَ غَداً رَجُلاً يُحِبُّ اللَّهَ وَرَسُولَهُ، وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ، يَفْتَحُ اللَّهُ عَلَى يَدَيْهِ.",
      "فَبَاتَ النَّاسُ يَدُوكُونَ لَيْلَتَهُمْ؛ أَيُّهُمْ يُعْطَاهَا.",
      "فَلَمَّا أَصْبَحُوا؛ غَدَوْا عَلَى رَسُولِ اللَّهِ ﷺ، كُلُّهُمْ يَرْجُو أَنْ يُعْطَاهَا، فَقَالَ: أَيْنَ عَلِيُّ بْنُ أَبِي طَالِبٍ؟ فَقِيلَ: هُوَ يَشْتَكِي عَيْنَيْهِ.",
      "فَأَرْسَلُوا إِلَيْهِ، فَأُتِيَ بِهِ، فَبَصَقَ فِي عَيْنَيْهِ، وَدَعَا لَهُ، فَبَرَأَ حَتَّى كَأَنْ لَمْ يَكُنْ بِهِ وَجَعٌ، فَأَعْطَاهُ الرَّايَةَ، وَقَالَ: انْفُذْ عَلَى رِسْلِكَ حَتَّى تَنْزِلَ بِسَاحَتِهِمْ، ثُمَّ ادْعُهُمْ إِلَى الإِسْلَامِ، وَأَخْبِرْهُمْ بِمَا يَجِبُ عَلَيْهِمْ مِنْ حَقِّ اللَّهِ تَعَالَى فِيهِ، فَوَاللَّهِ! لَأَنْ يَهْدِيَ اللَّهُ بِكَ رَجُلاً وَاحِداً خَيْرٌ لَكَ مِنْ حُمْرِ النَّعَمِ».",
      "قَوْلُهُ: «يَدُوكُونَ» أَيْ: يَخُوضُونَ."
    ]},
    { title: "[٦] باب تفسير التوحيد وشهادة أن لا إله إلا الله", paras: [
      "#بَابُ تَفْسِيرِ التَّوْحِيدِ وَشَهَادَةِ أَلَّا إِلَهَ إِلَّا اللَّهُ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿أُولَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ﴾ الآيَةَ.",
      "وَقَوْلُهُ تَعَالَى: ﴿وَإِذْ قَالَ إِبْرَاهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَرَاءٌ مِمَّا تَعْبُدُونَ * إِلَّا الَّذِي فَطَرَنِي﴾ الآيَةَ.",
      "وَقَوْلُهُ تَعَالَى: ﴿اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَاباً مِنْ دُونِ اللَّهِ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَاداً يُحِبُّونَهُمْ كَحُبِّ اللَّهِ﴾ الآيَةَ.",
      "فِي الصَّحِيحِ: عَنِ النَّبِيِّ ﷺ أَنَّهُ قَالَ: «مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ؛ حَرُمَ مَالُهُ وَدَمُهُ، وَحِسَابُهُ عَلَى اللَّهِ».",
      "وَشَرْحُ هَذِهِ التَّرْجَمَةِ مَا بَعْدَهَا مِنَ الأَبْوَابِ."
    ]},
    { title: "[٧] باب من الشرك لبس الحلقة والخيط ونحوهما", paras: [
      "#بَابٌ: مِنَ الشِّرْكِ لُبْسُ الْحَلْقَةِ وَالْخَيْطِ وَنَحْوِهِمَا؛ لِرَفْعِ الْبَلَاءِ أَوْ دَفْعِهِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿قُلْ أَفَرَأَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللَّهِ إِنْ أَرَادَنِيَ اللَّهُ بِضُرٍّ هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ﴾ الآيَةَ.",
      "عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رضي الله عنهما: «أَنَّ النَّبِيَّ ﷺ رَأَى رَجُلاً فِي يَدِهِ حَلْقَةٌ مِنْ صُفْرٍ، فَقَالَ: مَا هَذِهِ؟! قَالَ: مِنَ الْوَاهِنَةِ، قَالَ: انْزِعْهَا؛ فَإِنَّهَا لَا تَزِيدُكَ إِلَّا وَهْناً، فَإِنَّكَ لَوْ مِتَّ وَهِيَ عَلَيْكَ؛ مَا أَفْلَحْتَ أَبَداً» رَوَاهُ أَحْمَدُ بِسَنَدٍ لَا بَأْسَ بِهِ.",
      "وَلَهُ: عَنْ عُقْبَةَ بْنِ عَامِرٍ رضي الله عنه مَرْفُوعاً: «مَنْ تَعَلَّقَ تَمِيمَةً؛ فَلَا أَتَمَّ اللَّهُ لَهُ، وَمَنْ تَعَلَّقَ وَدَعَةً؛ فَلَا وَدَعَ اللَّهُ لَهُ».",
      "وَفِي لَفْظٍ: «مَنْ تَعَلَّقَ تَمِيمَةً؛ فَقَدْ أَشْرَكَ».",
      "وَعَنْ حُذَيْفَةَ رضي الله عنه: «أَنَّهُ رَأَى رَجُلاً فِي يَدِهِ خَيْطٌ مِنَ الْحُمَّى، فَقَطَعَهُ، وَتَلَا قَوْلَهُ تَعَالَى: ﴿وَمَا يُؤْمِنُ أَكْثَرُهُمْ بِاللَّهِ إِلَّا وَهُمْ مُشْرِكُونَ﴾» رَوَاهُ ابْنُ أَبِي حَاتِمٍ."
    ]},
    { title: "[٨] باب ما جاء في الرقى والتمائم", paras: [
      "#بَابُ مَا جَاءَ فِي الرُّقَى وَالتَّمَائِمِ",
      "فِي الصَّحِيحِ: عَنْ أَبِي بَشِيرٍ الأَنْصَارِيِّ رضي الله عنه: «أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ ﷺ فِي بَعْضِ أَسْفَارِهِ، فَأَرْسَلَ رَسُولاً: أَلَّا يَبْقَيَنَّ فِي رَقَبَةِ بَعِيرٍ قِلَادَةٌ مِنْ وَتَرٍ، أَوْ قِلَادَةٌ؛ إِلَّا قُطِعَتْ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّ الرُّقَى، وَالتَّمَائِمَ، وَالتِّوَلَةَ؛ شِرْكٌ» رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ.",
      "وَعَنْ عَبْدِ اللَّهِ بْنِ عُكَيْمٍ رضي الله عنه مَرْفُوعاً: «مَنْ تَعَلَّقَ شَيْئاً؛ وُكِلَ إِلَيْهِ» رَوَاهُ أَحْمَدُ وَالتِّرْمِذِيُّ.",
      "التَّمَائِمُ: شَيْءٌ يُعَلَّقُ عَلَى الأَوْلَادِ عَنِ الْعَيْنِ، لَكِنْ إِذَا كَانَ مِنَ الْقُرْآنِ؛ فَرَخَّصَ فِيهِ بَعْضُهُمْ، وَبَعْضُهُمْ لَمْ يُرَخِّصْ فِيهِ، وَيَجْعَلُهُ مِنَ الْمَنْهِيِّ عَنْهُ - مِنْهُمُ ابْنُ مَسْعُودٍ رضي الله عنه -.",
      "وَالرُّقَى: هِيَ الَّتِي تُسَمَّى الْعَزَائِمَ، وَخَصَّ مِنْهُ الدَّلِيلُ مَا خَلَا مِنَ الشِّرْكِ؛ فَقَدْ رَخَّصَ فِيهِ رَسُولُ اللَّهِ ﷺ مِنَ الْعَيْنِ وَالْحُمَةِ.",
      "وَالتِّوَلَةُ: شَيْءٌ يَصْنَعُونَهُ يَزْعُمُونَ أَنَّهُ يُحَبِّبُ الْمَرْأَةَ إِلَى زَوْجِهَا، وَالرَّجُلَ إِلَى امْرَأَتِهِ.",
      "وَرَوَى الإِمَامُ أَحْمَدُ: عَنْ رُوَيْفِعٍ رضي الله عنه قَالَ: قَالَ لِي رَسُولُ اللَّهِ ﷺ: «يَا رُوَيْفِعُ! لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ؛ فَأَخْبِرِ النَّاسَ أَنَّ مَنْ عَقَدَ لِحْيَتَهُ، أَوْ تَقَلَّدَ وَتَراً، أَوِ اسْتَنْجَى بِرَجِيعِ دَابَّةٍ أَوْ عَظْمٍ؛ فَإِنَّ مُحَمَّداً بَرِيءٌ مِنْهُ».",
      "وَعَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: «مَنْ قَطَعَ تَمِيمَةً مِنْ إِنْسَانٍ، كَانَ كَعَدْلِ رَقَبَةٍ» رَوَاهُ وَكِيعٌ.",
      "وَلَهُ: عَنْ إِبْرَاهِيمَ قَالَ: «كَانُوا يَكْرَهُونَ التَّمَائِمَ كُلَّهَا مِنَ الْقُرْآنِ وَغَيْرِ الْقُرْآنِ»."
    ]},
    { title: "[٩] باب من تبرك بشجرة أو حجر ونحوهما", paras: [
      "#بَابُ مَنْ تَبَرَّكَ بِشَجَرَةٍ أَوْ حَجَرٍ وَنَحْوِهِمَا",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى﴾ الآيَاتِ.",
      "عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ رضي الله عنه قَالَ: «خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ إِلَى حُنَيْنٍ، وَنَحْنُ حُدَثَاءُ عَهْدٍ بِكُفْرٍ، وَلِلْمُشْرِكِينَ سِدْرَةٌ يَعْكُفُونَ عِنْدَهَا وَيَنُوطُونَ بِهَا أَسْلِحَتَهُمْ، يُقَالُ لَهَا: ذَاتُ أَنْوَاطٍ.",
      "فَمَرَرْنَا بِسِدْرَةٍ، فَقُلْنَا: يَا رَسُولَ اللَّهِ! اجْعَلْ لَنَا ذَاتَ أَنْوَاطٍ كَمَا لَهُمْ ذَاتُ أَنْوَاطٍ، فَقَالَ رَسُولُ اللَّهِ ﷺ: اللَّهُ أَكْبَرُ! إِنَّهَا السُّنَنُ، قُلْتُمْ وَالَّذِي نَفْسِي بِيَدِهِ، كَمَا قَالَتْ بَنُو إِسْرَائِيلَ لِمُوسَى: ﴿اجْعَلْ لَنَا إِلَهاً كَمَا لَهُمْ آلِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ﴾، لَتَرْكَبُنَّ سَنَنَ مَنْ كَانَ قَبْلَكُمْ» رَوَاهُ التِّرْمِذِيُّ وَصَحَّحَهُ."
    ]},
    { title: "[١٠] باب ما جاء في الذبح لغير الله", paras: [
      "#بَابُ مَا جَاءَ فِي الذَّبْحِ لِغَيْرِ اللَّهِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ * لَا شَرِيكَ لَهُ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿فَصَلِّ لِرَبِّكَ وَانْحَرْ﴾.",
      "عَنْ عَلِيٍّ رضي الله عنه قَالَ: حَدَّثَنِي رَسُولُ اللَّهِ ﷺ بِأَرْبَعِ كَلِمَاتٍ: «لَعَنَ اللَّهُ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ، لَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَيْهِ، لَعَنَ اللَّهُ مَنْ آوَى مُحْدِثاً، لَعَنَ اللَّهُ مَنْ غَيَّرَ مَنَارَ الأَرْضِ» رَوَاهُ مُسْلِمٌ.",
      "وَعَنْ طَارِقِ بْنِ شِهَابٍ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «دَخَلَ الْجَنَّةَ رَجُلٌ فِي ذُبَابٍ، وَدَخَلَ النَّارَ رَجُلٌ فِي ذُبَابٍ، قَالُوا: وَكَيْفَ ذَلِكَ يَا رَسُولَ اللَّهِ؟",
      "قَالَ: مَرَّ رَجُلَانِ عَلَى قَوْمٍ لَهُمْ صَنَمٌ لَا يَجُوزُهُ أَحَدٌ حَتَّى يُقَرِّبَ لَهُ شَيْئاً.",
      "فَقَالُوا لِأَحَدِهِمَا: قَرِّبْ، قَالَ: لَيْسَ عِنْدِي شَيْءٌ أُقَرِّبُ، قَالُوا لَهُ: قَرِّبْ وَلَوْ ذُبَاباً، فَقَرَّبَ ذُبَاباً، فَخَلَّوْا سَبِيلَهُ؛ فَدَخَلَ النَّارَ.",
      "وَقَالُوا لِلآخَرِ: قَرِّبْ، قَالَ: مَا كُنْتُ لِأُقَرِّبَ لِأَحَدٍ شَيْئاً دُونَ اللَّهِ عَزَّ وَجَلَّ، فَضَرَبُوا عُنُقَهُ؛ فَدَخَلَ الْجَنَّةَ» رَوَاهُ أَحْمَدُ."
    ]},
    { title: "[١١] باب لا يذبح لله بمكان يذبح فيه لغير الله", paras: [
      "#بَابٌ: لَا يُذْبَحُ لِلَّهِ بِمَكَانٍ يُذْبَحُ فِيهِ لِغَيْرِ اللَّهِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿لَا تَقُمْ فِيهِ أَبَداً﴾ الآيَةَ.",
      "عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رضي الله عنه قَالَ: «نَذَرَ رَجُلٌ أَنْ يَنْحَرَ إِبِلاً بِبُوَانَةَ، فَسَأَلَ النَّبِيَّ ﷺ؟ فَقَالَ: هَلْ كَانَ فِيهَا وَثَنٌ مِنْ أَوْثَانِ الْجَاهِلِيَّةِ يُعْبَدُ؟ قَالُوا: لَا.",
      "قَالَ: هَلْ كَانَ فِيهَا عِيدٌ مِنْ أَعْيَادِهِمْ؟ قَالُوا: لَا.",
      "فَقَالَ رَسُولُ اللَّهِ ﷺ: أَوْفِ بِنَذْرِكَ؛ فَإِنَّهُ لَا وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ، وَلَا فِيمَا لَا يَمْلِكُ ابْنُ آدَمَ» رَوَاهُ أَبُو دَاوُدَ، وَإِسْنَادُهُ عَلَى شَرْطِهِمَا."
    ]},
    { title: "[١٢] باب من الشرك النذر لغير الله", paras: [
      "#بَابٌ: مِنَ الشِّرْكِ النَّذْرُ لِغَيْرِ اللَّهِ",
      "لِقَوْلِهِ: ﴿يُوفُونَ بِالنَّذْرِ﴾.",
      "وَقَوْلِهِ: ﴿وَمَا أَنْفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ﴾.",
      "وَفِي الصَّحِيحِ: عَنْ عَائِشَةَ رضي الله عنها أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ نَذَرَ أَنْ يُطِيعَ اللَّهَ فَلْيُطِعْهُ، وَمَنْ نَذَرَ أَنْ يَعْصِيَ اللَّهَ فَلَا يَعْصِهِ»."
    ]},
    { title: "[١٣] باب من الشرك الاستعاذة بغير الله", paras: [
      "#بَابٌ: مِنَ الشِّرْكِ الِاسْتِعَاذَةُ بِغَيْرِ اللَّهِ",
      "وَقَوْلُهُ تَعَالَى: ﴿وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنْسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ﴾ الآيَةَ.",
      "عَنْ خَوْلَةَ بِنْتِ حَكِيمٍ رضي الله عنها قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَنْ نَزَلَ مَنْزِلاً فَقَالَ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ؛ لَمْ يَضُرَّهُ شَيْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ» رَوَاهُ مُسْلِمٌ."
    ]},
    { title: "[١٤] باب من الشرك أن يستغيث بغير الله أو يدعو غيره", paras: [
      "#بَابٌ: مِنَ الشِّرْكِ أَنْ يَسْتَغِيثَ بِغَيْرِ اللَّهِ، أَوْ يَدْعُوَ غَيْرَهُ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَلَا تَدْعُ مِنْ دُونِ اللَّهِ مَا لَا يَنْفَعُكَ وَلَا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذاً مِنَ الظَّالِمِينَ * وَإِنْ يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿فَابْتَغُوا عِنْدَ اللَّهِ الرِّزْقَ وَاعْبُدُوهُ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لَا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ﴾ الآيَتَيْنِ.",
      "وَقَوْلُهُ: ﴿أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ﴾ الآيَةَ.",
      "رَوَى الطَّبَرَانِيُّ: «أَنَّهُ كَانَ فِي زَمَنِ النَّبِيِّ ﷺ مُنَافِقٌ يُؤْذِي الْمُؤْمِنِينَ، فَقَالَ بَعْضُهُمْ: قُومُوا بِنَا نَسْتَغِيثُ بِرَسُولِ اللَّهِ ﷺ مِنْ هَذَا الْمُنَافِقِ؛ فَقَالَ النَّبِيُّ ﷺ: إِنَّهُ لَا يُسْتَغَاثُ بِي، وَإِنَّمَا يُسْتَغَاثُ بِاللَّهِ»."
    ]},
    { title: "[١٥] باب قول الله تعالى: ﴿أيشركون ما لا يخلق شيئاً وهم يخلقون﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْئاً وَهُمْ يُخْلَقُونَ * وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْراً﴾ الآيَةَ",
      "وَقَوْلُهُ: ﴿وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ﴾ الآيَةَ.",
      "فِي الصَّحِيحِ: عَنْ أَنَسٍ رضي الله عنه قَالَ: «شُجَّ النَّبِيُّ ﷺ يَوْمَ أُحُدٍ، فَقَالَ: كَيْفَ يُفْلِحُ قَوْمٌ شَجُّوا نَبِيَّهُمْ؟! فَنَزَلَتْ: ﴿لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ﴾».",
      "وَفِيهِ: عَنِ ابْنِ عُمَرَ رضي الله عنهما: «أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ﷺ - إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فِي الرَّكْعَةِ الآخِرَةِ مِنَ الْفَجْرِ - يَقُولُ: اللَّهُمَّ الْعَنْ فُلَاناً، وَفُلَاناً، بَعْدَمَا يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ؛ فَأَنْزَلَ اللَّهُ: ﴿لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ﴾».",
      "وَفِي رِوَايَةٍ: «يَدْعُو عَلَى صَفْوَانَ بْنِ أُمَيَّةَ، وَسُهَيْلِ بْنِ عَمْرٍو، وَالْحَارِثِ بْنِ هِشَامٍ؛ فَنَزَلَتْ: ﴿لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ﴾».",
      "وَفِيهِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: «قَامَ رَسُولُ اللَّهِ ﷺ حِينَ أُنْزِلَ عَلَيْهِ: ﴿وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ﴾؛ قَالَ: يَا مَعْشَرَ قُرَيْشٍ! - أَوْ كَلِمَةً نَحْوَهَا - اشْتَرُوا أَنْفُسَكُمْ؛ لَا أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئاً.",
      "يَا عَبَّاسُ بْنَ عَبْدِ الْمُطَّلِبِ! لَا أُغْنِي عَنْكَ مِنَ اللَّهِ شَيْئاً.",
      "يَا صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ! لَا أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئاً.",
      "وَيَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ! سَلِينِي مَا شِئْتِ مِنْ مَالِي؛ لَا أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئاً»."
    ]},
    { title: "[١٦] باب قول الله تعالى: ﴿حتى إذا فزع عن قلوبهم﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ قَالُوا الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ﴾",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ ﷺ قَالَ: «إِذَا قَضَى اللَّهُ الأَمْرَ فِي السَّمَاءِ؛ ضَرَبَتِ الْمَلَائِكَةُ بِأَجْنِحَتِهَا خُضْعَاناً لِقَوْلِهِ، كَأَنَّهُ سِلْسِلَةٌ عَلَى صَفْوَانٍ، يَنْفُذُهُمْ ذَلِكَ، ﴿حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ قَالُوا الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ﴾، فَيَسْمَعُهَا مُسْتَرِقُ السَّمْعِ، وَمُسْتَرِقُ السَّمْعِ هَكَذَا، بَعْضُهُ فَوْقَ بَعْضٍ - وَصَفَهُ سُفْيَانُ بِكَفِّهِ، فَحَرَّفَهَا وَبَدَّدَ بَيْنَ أَصَابِعِهِ -.",
      "فَيَسْمَعُ الْكَلِمَةَ، فَيُلْقِيهَا إِلَى مَنْ تَحْتَهُ، ثُمَّ يُلْقِيهَا الآخَرُ إِلَى مَنْ تَحْتَهُ، حَتَّى يُلْقِيَهَا عَلَى لِسَانِ السَّاحِرِ أَوِ الْكَاهِنِ، فَرُبَّمَا أَدْرَكَهُ الشِّهَابُ قَبْلَ أَنْ يُلْقِيَهَا، وَرُبَّمَا أَلْقَاهَا قَبْلَ أَنْ يُدْرِكَهُ، فَيَكْذِبُ مَعَهَا مِئَةَ كَذْبَةٍ، فَيُقَالُ: أَلَيْسَ قَدْ قَالَ لَنَا يَوْمَ كَذَا وَكَذَا: كَذَا وَكَذَا؟ فَيُصَدَّقُ بِتِلْكَ الْكَلِمَةِ الَّتِي سُمِعَتْ مِنَ السَّمَاءِ».",
      "وَعَنِ النَّوَّاسِ بْنِ سَمْعَانَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «إِذَا أَرَادَ اللَّهُ أَنْ يُوحِيَ بِالأَمْرِ، تَكَلَّمَ بِالْوَحْيِ، أَخَذَتِ السَّمَاوَاتِ مِنْهُ رَجْفَةٌ - أَوْ قَالَ: رِعْدَةٌ شَدِيدَةٌ - خَوْفاً مِنَ اللَّهِ عَزَّ وَجَلَّ.",
      "فَإِذَا سَمِعَ ذَلِكَ أَهْلُ السَّمَاوَاتِ، صَعِقُوا، وَخَرُّوا لِلَّهِ سُجَّداً، فَيَكُونُ أَوَّلَ مَنْ يَرْفَعُ رَأْسَهُ جِبْرِيلُ، فَيُكَلِّمُهُ اللَّهُ مِنْ وَحْيِهِ بِمَا أَرَادَ.",
      "ثُمَّ يَمُرُّ جِبْرِيلُ عَلَى الْمَلَائِكَةِ، كُلَّمَا مَرَّ بِسَمَاءٍ سَأَلَهُ مَلَائِكَتُهَا: مَاذَا قَالَ رَبُّنَا يَا جِبْرِيلُ؟ فَيَقُولُ جِبْرِيلُ: قَالَ الْحَقَّ، وَهُوَ الْعَلِيُّ الْكَبِيرُ.",
      "قَالَ: فَيَقُولُونَ كُلُّهُمْ مِثْلَ مَا قَالَ جِبْرِيلُ، فَيَنْتَهِي جِبْرِيلُ بِالْوَحْيِ إِلَى حَيْثُ أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ»."
    ]},
    { title: "[١٧] باب الشفاعة", paras: [
      "#بَابُ الشَّفَاعَةِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَأَنْذِرْ بِهِ الَّذِينَ يَخَافُونَ أَنْ يُحْشَرُوا إِلَى رَبِّهِمْ لَيْسَ لَهُمْ مِنْ دُونِهِ وَلِيٌّ وَلَا شَفِيعٌ﴾.",
      "وَقَوْلُهُ: ﴿قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعاً﴾.",
      "وَقَوْلُهُ: ﴿مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ﴾.",
      "وَقَوْلُهُ: ﴿وَكَمْ مِنْ مَلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئاً إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللَّهُ لِمَنْ يَشَاءُ وَيَرْضَى﴾.",
      "وَقَوْلُهُ: ﴿قُلِ ادْعُوا الَّذِينَ زَعَمْتُمْ مِنْ دُونِ اللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِي السَّمَاوَاتِ وَلَا فِي الأَرْضِ وَمَا لَهُمْ فِيهِمَا مِنْ شِرْكٍ وَمَا لَهُ مِنْهُمْ مِنْ ظَهِيرٍ * وَلَا تَنْفَعُ الشَّفَاعَةُ عِنْدَهُ إِلَّا لِمَنْ أَذِنَ لَهُ﴾ الآيَةَ.",
      "قَالَ أَبُو الْعَبَّاسِ: «نَفَى اللَّهُ عَمَّا سِوَاهُ كُلَّ مَا يَتَعَلَّقُ بِهِ الْمُشْرِكُونَ - فَنَفَى أَنْ يَكُونَ لِغَيْرِهِ مُلْكٌ، أَوْ قِسْطٌ مِنْهُ، أَوْ يَكُونَ عَوْناً لِلَّهِ - وَلَمْ يَبْقَ إِلَّا الشَّفَاعَةُ، فَبَيَّنَ أَنَّهَا لَا تَنْفَعُ إِلَّا لِمَنْ أَذِنَ لَهُ الرَّبُّ؛ كَمَا قَالَ: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾.",
      "فَهَذِهِ الشَّفَاعَةُ الَّتِي يَظُنُّهَا الْمُشْرِكُونَ هِيَ مُنْتَفِيَةٌ يَوْمَ الْقِيَامَةِ؛ كَمَا نَفَاهَا الْقُرْآنُ.",
      "وَأَخْبَرَ النَّبِيُّ ﷺ: أَنَّهُ يَأْتِي فَيَسْجُدُ لِرَبِّهِ وَيَحْمَدُهُ، لَا يَبْدَأُ بِالشَّفَاعَةِ أَوَّلاً، ثُمَّ يُقَالُ لَهُ: ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ، وَسَلْ تُعْطَ، وَاشْفَعْ تُشَفَّعْ.",
      "وَقَالَ لَهُ أَبُو هُرَيْرَةَ رضي الله عنه: مَنْ أَسْعَدُ النَّاسِ بِشَفَاعَتِكَ يَوْمَ الْقِيَامَةِ؟ قَالَ: مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، خَالِصاً مِنْ قَلْبِهِ.",
      "فَتِلْكَ الشَّفَاعَةُ لِأَهْلِ الإِخْلَاصِ - بِإِذْنِ اللَّهِ -، وَلَا تَكُونُ لِمَنْ أَشْرَكَ بِاللَّهِ.",
      "وَحَقِيقَتُهُ: أَنَّ اللَّهَ سُبْحَانَهُ هُوَ الَّذِي يَتَفَضَّلُ عَلَى أَهْلِ الإِخْلَاصِ، فَيَغْفِرُ لَهُمْ بِوَاسِطَةِ دُعَاءِ مَنْ أَذِنَ لَهُ أَنْ يَشْفَعَ؛ لِيُكْرِمَهُ، وَيَنَالَ الْمَقَامَ الْمَحْمُودَ.",
      "فَالشَّفَاعَةُ الَّتِي نَفَاهَا الْقُرْآنُ مَا كَانَ فِيهَا شِرْكٌ، وَلِهَذَا أَثْبَتَ الشَّفَاعَةَ بِإِذْنِهِ فِي مَوَاضِعَ، وَقَدْ بَيَّنَ النَّبِيُّ ﷺ أَنَّهَا لَا تَكُونُ إِلَّا لِأَهْلِ التَّوْحِيدِ وَالإِخْلَاصِ» انْتَهَى كَلَامُهُ."
    ]},
    { title: "[١٨] باب قول الله تعالى: ﴿إنك لا تهدي من أحببت﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ﴾",
      "فِي الصَّحِيحِ: عَنِ ابْنِ الْمُسَيَّبِ، عَنْ أَبِيهِ قَالَ: «لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ؛ جَاءَهُ رَسُولُ اللَّهِ ﷺ وَعِنْدَهُ عَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ وَأَبُو جَهْلٍ، فَقَالَ لَهُ: يَا عَمِّ! قُلْ: لَا إِلَهَ إِلَّا اللَّهُ، كَلِمَةً أُحَاجُّ لَكَ بِهَا عِنْدَ اللَّهِ.",
      "فَقَالَا لَهُ: أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟! فَأَعَادَ عَلَيْهِ رَسُولُ اللَّهِ ﷺ، فَأَعَادَا، فَكَانَ آخِرَ مَا قَالَ: هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ، وَأَبَى أَنْ يَقُولَ: لَا إِلَهَ إِلَّا اللَّهُ.",
      "فَقَالَ النَّبِيُّ ﷺ: لَأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ؛ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ: ﴿مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى﴾، وَأَنْزَلَ اللَّهُ فِي أَبِي طَالِبٍ: ﴿إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ﴾»."
    ]},
    { title: "[١٩] باب ما جاء أن سبب كفر بني آدم الغلو في الصالحين", paras: [
      "#بَابُ مَا جَاءَ أَنَّ سَبَبَ كُفْرِ بَنِي آدَمَ وَتَرْكِهِمْ دِينَهُمْ هُوَ الْغُلُوُّ فِي الصَّالِحِينَ",
      "وَقَوْلُ اللَّهِ عَزَّ وَجَلَّ: ﴿يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ﴾.",
      "فِي الصَّحِيحِ: عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما فِي قَوْلِ اللَّهِ عَزَّ وَجَلَّ: ﴿وَقَالُوا لَا تَذَرُنَّ آلِهَتَكُمْ وَلَا تَذَرُنَّ وَدّاً وَلَا سُوَاعاً وَلَا يَغُوثَ وَيَعُوقَ وَنَسْراً﴾؛ قَالَ: «هَذِهِ أَسْمَاءُ رِجَالٍ صَالِحِينَ مِنْ قَوْمِ نُوحٍ، فَلَمَّا هَلَكُوا؛ أَوْحَى الشَّيْطَانُ إِلَى قَوْمِهِمْ: أَنِ انْصِبُوا إِلَى مَجَالِسِهِمُ الَّتِي كَانُوا يَجْلِسُونَ فِيهَا أَنْصَاباً، وَسَمُّوهَا بِأَسْمَائِهِمْ، فَفَعَلُوا، فَلَمْ تُعْبَدْ، حَتَّى إِذَا هَلَكَ أُولَئِكَ وَنُسِيَ الْعِلْمُ؛ عُبِدَتْ».",
      "وَقَالَ ابْنُ الْقَيِّمِ: «قَالَ غَيْرُ وَاحِدٍ مِنَ السَّلَفِ: لَمَّا مَاتُوا؛ عَكَفُوا عَلَى قُبُورِهِمْ، ثُمَّ صَوَّرُوا تَمَاثِيلَهُمْ، ثُمَّ طَالَ عَلَيْهِمُ الأَمَدُ؛ فَعَبَدُوهُمْ».",
      "وَعَنْ عُمَرَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا تُطْرُونِي كَمَا أَطْرَتِ النَّصَارَى ابْنَ مَرْيَمَ، إِنَّمَا أَنَا عَبْدٌ، فَقُولُوا: عَبْدُ اللَّهِ وَرَسُولُهُ» أَخْرَجَاهُ.",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «إِيَّاكُمْ وَالْغُلُوَّ، فَإِنَّمَا أَهْلَكَ مَنْ كَانَ قَبْلَكُمُ الْغُلُوُّ» حَدِيثٌ صَحِيحٌ.",
      "وَلِمُسْلِمٍ: عَنِ ابْنِ مَسْعُودٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «هَلَكَ الْمُتَنَطِّعُونَ - قَالَهَا ثَلَاثاً -»."
    ]},
    { title: "[٢٠] باب التغليظ فيمن عبد الله عند قبر رجل صالح", paras: [
      "#بَابُ مَا جَاءَ مِنَ التَّغْلِيظِ فِيمَنْ عَبَدَ اللَّهَ عِنْدَ قَبْرِ رَجُلٍ صَالِحٍ؛ فَكَيْفَ إِذَا عَبَدَهُ؟!",
      "فِي الصَّحِيحِ: عَنْ عَائِشَةَ رضي الله عنها: «أَنَّ أُمَّ سَلَمَةَ ذَكَرَتْ لِرَسُولِ اللَّهِ ﷺ كَنِيسَةً رَأَتْهَا بِأَرْضِ الْحَبَشَةِ، وَمَا فِيهَا مِنَ الصُّوَرِ، فَقَالَ: أُولَئِكِ إِذَا مَاتَ فِيهِمُ الرَّجُلُ الصَّالِحُ - أَوِ الْعَبْدُ الصَّالِحُ - بَنَوْا عَلَى قَبْرِهِ مَسْجِداً، وَصَوَّرُوا فِيهِ تِلْكَ الصُّوَرَ، أُولَئِكِ شِرَارُ الْخَلْقِ عِنْدَ اللَّهِ».",
      "فَهَؤُلَاءِ جَمَعُوا بَيْنَ الْفِتْنَتَيْنِ: فِتْنَةِ الْقُبُورِ، وَفِتْنَةِ التَّمَاثِيلِ.",
      "وَلَهُمَا: عَنْهَا رضي الله عنها قَالَتْ: «لَمَّا نُزِلَ بِرَسُولِ اللَّهِ ﷺ، طَفِقَ يَطْرَحُ خَمِيصَةً لَهُ عَلَى وَجْهِهِ، فَإِذَا اغْتَمَّ بِهَا كَشَفَهَا، فَقَالَ - وَهُوَ كَذَلِكَ -: لَعْنَةُ اللَّهِ عَلَى الْيَهُودِ وَالنَّصَارَى، اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ - يُحَذِّرُ مَا صَنَعُوا -، وَلَوْلَا ذَاكَ أُبْرِزَ قَبْرُهُ، غَيْرَ أَنَّهُ خُشِيَ أَنْ يُتَّخَذَ مَسْجِداً -» أَخْرَجَاهُ.",
      "وَلِمُسْلِمٍ: عَنْ جُنْدُبٍ رضي الله عنه قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ قَبْلَ أَنْ يَمُوتَ بِخَمْسٍ وَهُوَ يَقُولُ: «إِنِّي أَبْرَأُ إِلَى اللَّهِ أَنْ يَكُونَ لِي مِنْكُمْ خَلِيلٌ، فَإِنَّ اللَّهَ قَدِ اتَّخَذَنِي خَلِيلاً كَمَا اتَّخَذَ إِبْرَاهِيمَ خَلِيلاً، وَلَوْ كُنْتُ مُتَّخِذاً مِنْ أُمَّتِي خَلِيلاً؛ لَاتَّخَذْتُ أَبَا بَكْرٍ خَلِيلاً.",
      "أَلَا وَإِنَّ مَنْ كَانَ قَبْلَكُمْ كَانُوا يَتَّخِذُونَ قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ، أَلَا فَلَا تَتَّخِذُوا الْقُبُورَ مَسَاجِدَ؛ إِنِّي أَنْهَاكُمْ عَنْ ذَلِكَ».",
      "فَقَدْ نَهَى عَنْهُ فِي آخِرِ حَيَاتِهِ، ثُمَّ إِنَّهُ لَعَنَ - وَهُوَ فِي السِّيَاقِ - مَنْ فَعَلَهُ.",
      "وَالصَّلَاةُ عِنْدَهَا مِنْ ذَلِكَ - وَإِنْ لَمْ يُبْنَ مَسْجِدٌ - وَهُوَ مَعْنَى قَوْلِهَا: «خُشِيَ أَنْ يُتَّخَذَ مَسْجِداً»؛ فَإِنَّ الصَّحَابَةَ لَمْ يَكُونُوا لِيَبْنُوا حَوْلَ قَبْرِهِ مَسْجِداً.",
      "وَكُلُّ مَوْضِعٍ قُصِدَتِ الصَّلَاةُ فِيهِ فَقَدِ اتُّخِذَ مَسْجِداً؛ بَلْ كُلُّ مَوْضِعٍ يُصَلَّى فِيهِ يُسَمَّى مَسْجِداً؛ كَمَا قَالَ النَّبِيُّ ﷺ: «جُعِلَتْ لِيَ الأَرْضُ مَسْجِداً وَطَهُوراً».",
      "وَلِأَحْمَدَ بِسَنَدٍ جَيِّدٍ: عَنِ ابْنِ مَسْعُودٍ رضي الله عنه مَرْفُوعاً: «إِنَّ مِنْ شِرَارِ النَّاسِ: مَنْ تُدْرِكُهُمُ السَّاعَةُ وَهُمْ أَحْيَاءٌ، وَالَّذِينَ يَتَّخِذُونَ الْقُبُورَ مَسَاجِدَ». وَرَوَاهُ أَبُو حَاتِمٍ فِي «صَحِيحِهِ»."
    ]},
    { title: "[٢١] باب الغلو في قبور الصالحين يصيرها أوثاناً", paras: [
      "#بَابُ مَا جَاءَ أَنَّ الْغُلُوَّ فِي قُبُورِ الصَّالِحِينَ يُصَيِّرُهَا أَوْثَاناً تُعْبَدُ مِنْ دُونِ اللَّهِ",
      "رَوَى مَالِكٌ فِي «الْمُوَطَّأِ»: أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «اللَّهُمَّ لَا تَجْعَلْ قَبْرِي وَثَناً يُعْبَدُ، اشْتَدَّ غَضَبُ اللَّهِ عَلَى قَوْمٍ اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ».",
      "وَلِابْنِ جَرِيرٍ بِسَنَدِهِ: عَنْ سُفْيَانَ، عَنْ مَنْصُورٍ، عَنْ مُجَاهِدٍ فِي قَوْلِهِ: ﴿أَفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى﴾؛ قَالَ: «كَانَ يَلُتُّ لَهُمُ السَّوِيقَ، فَمَاتَ؛ فَعَكَفُوا عَلَى قَبْرِهِ».",
      "وَكَذَا قَالَ أَبُو الْجَوْزَاءِ، عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: «كَانَ يَلُتُّ السَّوِيقَ لِلْحَاجِّ».",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: «لَعَنَ رَسُولُ اللَّهِ ﷺ زَائِرَاتِ الْقُبُورِ، وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ وَالسُّرُجَ» رَوَاهُ أَهْلُ السُّنَنِ."
    ]},
    { title: "[٢٢] باب حماية المصطفى ﷺ جناب التوحيد", paras: [
      "#بَابُ مَا جَاءَ فِي حِمَايَةِ الْمُصْطَفَى ﷺ جَنَابَ التَّوْحِيدِ، وَسَدِّهِ كُلَّ طَرِيقٍ يُوصِلُ إِلَى الشِّرْكِ",
      "وَقَوْلُهُ تَعَالَى: ﴿لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ﴾ الآيَةَ.",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا تَجْعَلُوا بُيُوتَكُمْ قُبُوراً، وَلَا تَجْعَلُوا قَبْرِي عِيداً، وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلَاتَكُمْ تَبْلُغُنِي حَيْثُ كُنْتُمْ» رَوَاهُ أَبُو دَاوُدَ بِإِسْنَادٍ حَسَنٍ، رُوَاتُهُ ثِقَاتٌ.",
      "وَعَنْ عَلِيِّ بْنِ الْحُسَيْنِ: «أَنَّهُ رَأَى رَجُلاً يَجِيءُ إِلَى فُرْجَةٍ كَانَتْ عِنْدَ قَبْرِ النَّبِيِّ ﷺ، فَيَدْخُلُ فِيهَا، فَيَدْعُو، فَنَهَاهُ، وَقَالَ: أَلَا أُحَدِّثُكُمْ حَدِيثاً سَمِعْتُهُ مِنْ أَبِي، عَنْ جَدِّي، عَنْ رَسُولِ اللَّهِ ﷺ قَالَ: لَا تَتَّخِذُوا قَبْرِي عِيداً، وَلَا بُيُوتَكُمْ قُبُوراً؛ فَإِنَّ تَسْلِيمَكُمْ يَبْلُغُنِي أَيْنَمَا كُنْتُمْ» رَوَاهُ فِي «الْمُخْتَارَةِ»."
    ]},
    { title: "[٢٣] باب ما جاء أن بعض هذه الأمة يعبد الأوثان", paras: [
      "#بَابُ مَا جَاءَ أَنَّ بَعْضَ هَذِهِ الأُمَّةِ يَعْبُدُ الأَوْثَانَ",
      "وَقَوْلُهُ تَعَالَى: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيباً مِنَ الْكِتَابِ يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾.",
      "وَقَوْلُهُ تَعَالَى: ﴿قُلْ هَلْ أُنَبِّئُكُمْ بِشَرٍّ مِنْ ذَلِكَ مَثُوبَةً عِنْدَ اللَّهِ مَنْ لَعَنَهُ اللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ الْقِرَدَةَ وَالْخَنَازِيرَ وَعَبَدَ الطَّاغُوتَ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿قَالَ الَّذِينَ غَلَبُوا عَلَى أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِمْ مَسْجِداً﴾.",
      "عَنْ أَبِي سَعِيدٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَتَتَّبِعُنَّ سَنَنَ مَنْ كَانَ قَبْلَكُمْ حَذْوَ الْقُذَّةِ بِالْقُذَّةِ، حَتَّى لَوْ دَخَلُوا جُحْرَ ضَبٍّ لَدَخَلْتُمُوهُ، قَالُوا: يَا رَسُولَ اللَّهِ! الْيَهُودُ وَالنَّصَارَى؟ قَالَ: فَمَنْ؟!» أَخْرَجَاهُ.",
      "وَلِمُسْلِمٍ: عَنْ ثَوْبَانَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «إِنَّ اللَّهَ زَوَى لِيَ الأَرْضَ، فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا، وَإِنَّ أُمَّتِي سَيَبْلُغُ مُلْكُهَا مَا زُوِيَ لِي مِنْهَا، وَأُعْطِيتُ الْكَنْزَيْنِ - الأَحْمَرَ وَالأَبْيَضَ -.",
      "وَإِنِّي سَأَلْتُ رَبِّي لِأُمَّتِي أَلَّا يُهْلِكَهَا بِسَنَةٍ بِعَامَّةٍ، وَأَلَّا يُسَلِّطَ عَلَيْهِمْ عَدُوّاً مِنْ سِوَى أَنْفُسِهِمْ فَيَسْتَبِيحَ بَيْضَتَهُمْ.",
      "وَإِنَّ رَبِّي قَالَ: يَا مُحَمَّدُ! إِنِّي إِذَا قَضَيْتُ قَضَاءً فَإِنَّهُ لَا يُرَدُّ، وَإِنِّي أَعْطَيْتُكَ لِأُمَّتِكَ أَلَّا أُهْلِكَهُمْ بِسَنَةٍ بِعَامَّةٍ، وَأَلَّا أُسَلِّطَ عَلَيْهِمْ عَدُوّاً مِنْ سِوَى أَنْفُسِهِمْ فَيَسْتَبِيحَ بَيْضَتَهُمْ، وَلَوِ اجْتَمَعَ عَلَيْهِمْ مَنْ بِأَقْطَارِهَا، حَتَّى يَكُونَ بَعْضُهُمْ يُهْلِكُ بَعْضاً، وَيَسْبِي بَعْضُهُمْ بَعْضاً».",
      "وَرَوَاهُ الْبَرْقَانِيُّ فِي «صَحِيحِهِ»، وَزَادَ: «وَإِنَّمَا أَخَافُ عَلَى أُمَّتِي الأَئِمَّةَ الْمُضِلِّينَ، وَإِذَا وَقَعَ عَلَيْهِمُ السَّيْفُ؛ لَمْ يُرْفَعْ إِلَى يَوْمِ الْقِيَامَةِ.",
      "وَلَا تَقُومُ السَّاعَةُ حَتَّى يَلْحَقَ حَيٌّ مِنْ أُمَّتِي بِالْمُشْرِكِينَ، وَحَتَّى تَعْبُدَ فِئَامٌ مِنْ أُمَّتِي الأَوْثَانَ.",
      "وَإِنَّهُ سَيَكُونُ فِي أُمَّتِي كَذَّابُونَ ثَلَاثُونَ، كُلُّهُمْ يَزْعُمُ أَنَّهُ نَبِيٌّ، وَأَنَا خَاتَمُ النَّبِيِّينَ، لَا نَبِيَّ بَعْدِي.",
      "وَلَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ مَنْصُورَةً، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللَّهِ تَبَارَكَ وَتَعَالَى»."
    ]},
    { title: "[٢٤] باب ما جاء في السحر", paras: [
      "#بَابُ مَا جَاءَ فِي السِّحْرِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الآخِرَةِ مِنْ خَلَاقٍ﴾.",
      "وَقَوْلُهُ: ﴿يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾.",
      "قَالَ عُمَرُ: «الْجِبْتُ: السِّحْرُ، وَالطَّاغُوتُ: الشَّيْطَانُ».",
      "وَقَالَ جَابِرٌ: «الطَّوَاغِيتُ: كُهَّانٌ، كَانَ يَنْزِلُ عَلَيْهِمُ الشَّيْطَانُ فِي كُلِّ حَيٍّ وَاحِدٌ».",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ، قَالُوا: يَا رَسُولَ اللَّهِ! وَمَا هُنَّ؟ قَالَ: الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ» أَخْرَجَاهُ.",
      "وَعَنْ جُنْدُبٍ مَرْفُوعاً: «حَدُّ السَّاحِرِ: ضَرْبُهُ بِالسَّيْفِ» رَوَاهُ التِّرْمِذِيُّ، وَقَالَ: «الصَّحِيحُ: أَنَّهُ مَوْقُوفٌ».",
      "وَفِي «صَحِيحِ الْبُخَارِيِّ»: عَنْ بَجَالَةَ بْنِ عَبَدَةَ قَالَ: «كَتَبَ عُمَرُ بْنُ الْخَطَّابِ رضي الله عنه: أَنِ اقْتُلُوا كُلَّ سَاحِرٍ وَسَاحِرَةٍ. قَالَ: فَقَتَلْنَا ثَلَاثَ سَوَاحِرَ».",
      "وَصَحَّ عَنْ حَفْصَةَ رضي الله عنها: «أَنَّهَا أَمَرَتْ بِقَتْلِ جَارِيَةٍ لَهَا سَحَرَتْهَا؛ فَقُتِلَتْ».",
      "وَكَذَلِكَ: صَحَّ عَنْ جُنْدُبٍ.",
      "قَالَ أَحْمَدُ: «عَنْ ثَلَاثَةٍ مِنْ أَصْحَابِ النَّبِيِّ ﷺ»."
    ]},
    { title: "[٢٥] باب بيان شيء من أنواع السحر", paras: [
      "#بَابُ بَيَانِ شَيْءٍ مِنْ أَنْوَاعِ السِّحْرِ",
      "قَالَ أَحْمَدُ: حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا عَوْفٌ، عَنْ حَيَّانَ بْنِ الْعَلَاءِ، حَدَّثَنَا قَطَنُ بْنُ قَبِيصَةَ، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ النَّبِيَّ ﷺ قَالَ: «إِنَّ الْعِيَافَةَ، وَالطَّرْقَ، وَالطِّيَرَةَ؛ مِنَ الْجِبْتِ».",
      "قَالَ عَوْفٌ: «الْعِيَافَةُ: زَجْرُ الطَّيْرِ، وَالطَّرْقُ: الْخَطُّ يُخَطُّ بِالأَرْضِ، وَالْجِبْتُ - قَالَ الْحَسَنُ -: إِنَّهُ الشَّيْطَانُ» إِسْنَادُهُ جَيِّدٌ.",
      "وَلِأَبِي دَاوُدَ، وَالنَّسَائِيِّ، وَابْنِ حِبَّانَ فِي «صَحِيحِهِ»: الْمُسْنَدُ مِنْهُ.",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنِ اقْتَبَسَ شُعْبَةً مِنَ النُّجُومِ؛ فَقَدِ اقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ، زَادَ مَا زَادَ» رَوَاهُ أَبُو دَاوُدَ، بِإِسْنَادٍ صَحِيحٍ.",
      "وَلِلنَّسَائِيِّ: مِنْ حَدِيثِ أَبِي هُرَيْرَةَ رضي الله عنه: «مَنْ عَقَدَ عُقْدَةً ثُمَّ نَفَثَ فِيهَا فَقَدْ سَحَرَ، وَمَنْ سَحَرَ فَقَدْ أَشْرَكَ، وَمَنْ تَعَلَّقَ شَيْئاً وُكِلَ إِلَيْهِ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أَلَا هَلْ أُنَبِّئُكُمْ مَا الْعَضْهُ؟ هِيَ النَّمِيمَةُ - الْقَالَةُ بَيْنَ النَّاسِ -» رَوَاهُ مُسْلِمٌ.",
      "وَلَهُمَا: عَنِ ابْنِ عُمَرَ رضي الله عنهما أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «إِنَّ مِنَ الْبَيَانِ لَسِحْراً»."
    ]},
    { title: "[٢٦] باب ما جاء في الكهان ونحوهم", paras: [
      "#بَابُ مَا جَاءَ فِي الْكُهَّانِ وَنَحْوِهِمْ",
      "رَوَى مُسْلِمٌ فِي «صَحِيحِهِ»: عَنْ بَعْضِ أَزْوَاجِ النَّبِيِّ ﷺ، عَنِ النَّبِيِّ ﷺ أَنَّهُ قَالَ: «مَنْ أَتَى عَرَّافاً فَسَأَلَهُ عَنْ شَيْءٍ، فَصَدَّقَهُ؛ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ يَوْماً».",
      "وَعَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ أَتَى كَاهِناً فَصَدَّقَهُ بِمَا يَقُولُ؛ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ ﷺ» رَوَاهُ أَبُو دَاوُدَ.",
      "وَلِلأَرْبَعَةِ وَالْحَاكِمِ - وَقَالَ: «صَحِيحٌ عَلَى شَرْطِهِمَا» -: عَنِ النَّبِيِّ ﷺ: «مَنْ أَتَى عَرَّافاً أَوْ كَاهِناً فَصَدَّقَهُ بِمَا يَقُولُ؛ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ ﷺ».",
      "وَلِأَبِي يَعْلَى - بِسَنَدٍ جَيِّدٍ - عَنِ ابْنِ مَسْعُودٍ رضي الله عنه مِثْلُهُ: مَوْقُوفاً.",
      "وَعَنْ عِمْرَانَ بْنِ حُصَيْنٍ رضي الله عنه مَرْفُوعاً: «لَيْسَ مِنَّا مَنْ تَطَيَّرَ أَوْ تُطُيِّرَ لَهُ، أَوْ تَكَهَّنَ أَوْ تُكُهِّنَ لَهُ، أَوْ سَحَرَ أَوْ سُحِرَ لَهُ، وَمَنْ أَتَى كَاهِناً فَصَدَّقَهُ بِمَا يَقُولُ؛ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ ﷺ» رَوَاهُ الْبَزَّارُ بِإِسْنَادٍ جَيِّدٍ.",
      "وَرَوَاهُ الطَّبَرَانِيُّ بِإِسْنَادٍ حَسَنٍ مِنْ حَدِيثِ ابْنِ عَبَّاسٍ رضي الله عنهما: دُونَ قَوْلِهِ: «وَمَنْ أَتَى...» إِلَى آخِرِهِ.",
      "قَالَ الْبَغَوِيُّ: «الْعَرَّافُ: الَّذِي يَدَّعِي مَعْرِفَةَ الأُمُورِ بِمُقَدِّمَاتٍ يَسْتَدِلُّ بِهَا عَلَى الْمَسْرُوقِ، وَمَكَانِ الضَّالَّةِ، وَنَحْوِ ذَلِكَ».",
      "وَقِيلَ: هُوَ الْكَاهِنُ.",
      "وَالْكَاهِنُ: هُوَ الَّذِي يُخْبِرُ عَنِ الْمُغَيَّبَاتِ فِي الْمُسْتَقْبَلِ.",
      "وَقِيلَ: هُوَ الَّذِي يُخْبِرُ عَمَّا فِي الضَّمِيرِ.",
      "وَقَالَ أَبُو الْعَبَّاسِ ابْنُ تَيْمِيَّةَ: «الْعَرَّافُ: اسْمٌ لِلْكَاهِنِ، وَالْمُنَجِّمِ، وَالرَّمَّالِ، وَنَحْوِهِمْ، مِمَّنْ يَتَكَلَّمُ فِي مَعْرِفَةِ الأُمُورِ بِهَذِهِ الطُّرُقِ».",
      "وَقَالَ ابْنُ عَبَّاسٍ فِي قَوْمٍ يَكْتُبُونَ «أَبَا جَادٍ»، وَيَنْظُرُونَ فِي النُّجُومِ: «مَا أَرَى مَنْ فَعَلَ ذَلِكَ لَهُ عِنْدَ اللَّهِ مِنْ خَلَاقٍ»."
    ]},
    { title: "[٢٧] باب ما جاء في النشرة", paras: [
      "#بَابُ مَا جَاءَ فِي النُّشْرَةِ",
      "عَنْ جَابِرٍ: «أَنَّ رَسُولَ اللَّهِ ﷺ سُئِلَ عَنِ النُّشْرَةِ؟ فَقَالَ: هِيَ مِنْ عَمَلِ الشَّيْطَانِ» رَوَاهُ أَحْمَدُ بِسَنَدٍ جَيِّدٍ، وَأَبُو دَاوُدَ، وَقَالَ: «سُئِلَ أَحْمَدُ عَنْهَا؟ فَقَالَ: ابْنُ مَسْعُودٍ يَكْرَهُ هَذَا كُلَّهُ».",
      "وَفِي «الْبُخَارِيِّ»: عَنْ قَتَادَةَ: «قُلْتُ لِابْنِ الْمُسَيَّبِ: رَجُلٌ بِهِ طِبٌّ، أَوْ يُؤَخَّذُ عَنِ امْرَأَتِهِ؛ أَيُحَلُّ عَنْهُ أَوْ يُنَشَّرُ؟ قَالَ: لَا بَأْسَ بِهِ؛ إِنَّمَا يُرِيدُونَ بِهِ الإِصْلَاحَ، فَأَمَّا مَا يَنْفَعُ؛ فَلَمْ يُنْهَ عَنْهُ» انْتَهَى.",
      "وَرُوِيَ عَنِ الْحَسَنِ: «لَا يَحُلُّ السِّحْرَ إِلَّا سَاحِرٌ».",
      "قَالَ ابْنُ الْقَيِّمِ: «النُّشْرَةُ: حَلُّ السِّحْرِ عَنِ الْمَسْحُورِ، وَهِيَ نَوْعَانِ:",
      "حَلٌّ بِسِحْرٍ مِثْلِهِ، وَهُوَ الَّذِي مِنْ عَمَلِ الشَّيْطَانِ، وَعَلَيْهِ يُحْمَلُ قَوْلُ الْحَسَنِ - فَيَتَقَرَّبُ النَّاشِرُ وَالْمُنْتَشِرُ إِلَى الشَّيْطَانِ بِمَا يُحِبُّ، فَيُبْطِلُ عَمَلَهُ عَنِ الْمَسْحُورِ -.",
      "وَالثَّانِي: النُّشْرَةُ بِالرُّقْيَةِ، وَالتَّعَوُّذَاتِ، وَالدَّعَوَاتِ، وَالأَدْوِيَةِ الْمُبَاحَةِ؛ فَهَذَا جَائِزٌ»."
    ]},
    { title: "[٢٨] باب ما جاء في التطير", paras: [
      "#بَابُ مَا جَاءَ فِي التَّطَيُّرِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿أَلَا إِنَّمَا طَائِرُهُمْ عِنْدَ اللَّهِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ﴾.",
      "وَقَوْلُهُ: ﴿قَالُوا طَائِرُكُمْ مَعَكُمْ﴾ الآيَةَ.",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا عَدْوَى، وَلَا طِيَرَةَ، وَلَا هَامَةَ، وَلَا صَفَرَ» أَخْرَجَاهُ.",
      "زَادَ مُسْلِمٌ: «وَلَا نَوْءَ، وَلَا غُولَ».",
      "وَلَهُمَا: عَنْ أَنَسٍ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا عَدْوَى، وَلَا طِيَرَةَ، وَيُعْجِبُنِي الْفَأْلُ، قَالُوا: وَمَا الْفَأْلُ؟ قَالَ: الْكَلِمَةُ الطَّيِّبَةُ».",
      "وَلِأَبِي دَاوُدَ بِسَنَدٍ صَحِيحٍ: عَنْ عُقْبَةَ بْنِ عَامِرٍ رضي الله عنه قَالَ: «ذُكِرَتِ الطِّيَرَةُ عِنْدَ رَسُولِ اللَّهِ ﷺ، فَقَالَ: أَحْسَنُهَا الْفَأْلُ، وَلَا تَرُدُّ مُسْلِماً، فَإِذَا رَأَى أَحَدُكُمْ مَا يَكْرَهُ؛ فَلْيَقُلْ: اللَّهُمَّ لَا يَأْتِي بِالْحَسَنَاتِ إِلَّا أَنْتَ، وَلَا يَدْفَعُ السَّيِّئَاتِ إِلَّا أَنْتَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه مَرْفُوعاً: «الطِّيَرَةُ شِرْكٌ، الطِّيَرَةُ شِرْكٌ، وَمَا مِنَّا إِلَّا، وَلَكِنَّ اللَّهَ يُذْهِبُهُ بِالتَّوَكُّلِ» رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَصَحَّحَهُ، وَبَيَّنَ أَنَّ آخِرَهُ مِنْ قَوْلِ ابْنِ مَسْعُودٍ.",
      "وَلِأَحْمَدَ: مِنْ حَدِيثِ ابْنِ عَمْرٍو رضي الله عنهما: «مَنْ رَدَّتْهُ الطِّيَرَةُ مِنْ حَاجَتِهِ؛ فَقَدْ أَشْرَكَ، قَالُوا: فَمَا كَفَّارَةُ ذَلِكَ؟ قَالَ: أَنْ تَقُولَ: اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا طَيْرَ إِلَّا طَيْرُكَ، وَلَا إِلَهَ غَيْرُكَ».",
      "وَلَهُ: مِنْ حَدِيثِ الْفَضْلِ بْنِ عَبَّاسٍ رضي الله عنهما: «إِنَّمَا الطِّيَرَةُ مَا أَمْضَاكَ، أَوْ رَدَّكَ»."
    ]},
    { title: "[٢٩] باب ما جاء في التنجيم", paras: [
      "#بَابُ مَا جَاءَ فِي التَّنْجِيمِ",
      "قَالَ الْبُخَارِيُّ فِي «صَحِيحِهِ»: قَالَ قَتَادَةُ: «خَلَقَ اللَّهُ هَذِهِ النُّجُومَ لِثَلَاثٍ: زِينَةً لِلسَّمَاءِ، وَرُجُوماً لِلشَّيَاطِينِ، وَعَلَامَاتٍ يُهْتَدَى بِهَا، فَمَنْ تَأَوَّلَ فِيهَا غَيْرَ ذَلِكَ؛ أَخْطَأَ، وَأَضَاعَ نَصِيبَهُ، وَتَكَلَّفَ مَا لَا عِلْمَ لَهُ بِهِ» انْتَهَى.",
      "وَكَرِهَ قَتَادَةُ: تَعَلُّمَ مَنَازِلِ الْقَمَرِ، وَلَمْ يُرَخِّصِ ابْنُ عُيَيْنَةَ فِيهِ. ذَكَرَهُ حَرْبٌ عَنْهُمَا.",
      "وَرَخَّصَ فِي تَعَلُّمِ الْمَنَازِلِ: أَحْمَدُ، وَإِسْحَاقُ.",
      "وَعَنْ أَبِي مُوسَى رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «ثَلَاثَةٌ لَا يَدْخُلُونَ الْجَنَّةَ: مُدْمِنُ الْخَمْرِ، وَقَاطِعُ الرَّحِمِ، وَمُصَدِّقٌ بِالسِّحْرِ» رَوَاهُ أَحْمَدُ، وَابْنُ حِبَّانَ فِي «صَحِيحِهِ»."
    ]},
    { title: "[٣٠] باب ما جاء في الاستسقاء بالأنواء", paras: [
      "#بَابُ مَا جَاءَ فِي الِاسْتِسْقَاءِ بِالأَنْوَاءِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ﴾.",
      "عَنْ أَبِي مَالِكٍ الأَشْعَرِيِّ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أَرْبَعٌ فِي أُمَّتِي مِنْ أَمْرِ الْجَاهِلِيَّةِ لَا يَتْرُكُونَهُنَّ: الْفَخْرُ بِالأَحْسَابِ، وَالطَّعْنُ فِي الأَنْسَابِ، وَالِاسْتِسْقَاءُ بِالنُّجُومِ، وَالنِّيَاحَةُ، وَقَالَ: النَّائِحَةُ إِذَا لَمْ تَتُبْ قَبْلَ مَوْتِهَا؛ تُقَامُ يَوْمَ الْقِيَامَةِ وَعَلَيْهَا سِرْبَالٌ مِنْ قَطِرَانٍ، وَدِرْعٌ مِنْ جَرَبٍ» رَوَاهُ مُسْلِمٌ.",
      "وَلَهُمَا: عَنْ زَيْدِ بْنِ خَالِدٍ رضي الله عنه قَالَ: «صَلَّى لَنَا رَسُولُ اللَّهِ ﷺ صَلَاةَ الصُّبْحِ بِالْحُدَيْبِيَةِ عَلَى إِثْرِ سَمَاءٍ كَانَتْ مِنَ اللَّيْلِ، فَلَمَّا انْصَرَفَ؛ أَقْبَلَ عَلَى النَّاسِ، فَقَالَ: هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ؟! قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ.",
      "قَالَ: قَالَ: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ:",
      "فَأَمَّا مَنْ قَالَ: مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ؛ فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالْكَوْكَبِ.",
      "وَأَمَّا مَنْ قَالَ: مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا؛ فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالْكَوْكَبِ».",
      "وَلَهُمَا: مِنْ حَدِيثِ ابْنِ عَبَّاسٍ رضي الله عنهما: مَعْنَاهُ، وَفِيهِ: «قَالَ بَعْضُهُمْ: لَقَدْ صَدَقَ نَوْءُ كَذَا وَكَذَا، فَأَنْزَلَ اللَّهُ هَذِهِ الآيَةَ: ﴿فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ﴾ إِلَى قَوْلِهِ: ﴿تُكَذِّبُونَ﴾»."
    ]},
    { title: "[٣١] باب قول الله تعالى: ﴿ومن الناس من يتخذ من دون الله أنداداً﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَاداً يُحِبُّونَهُمْ كَحُبِّ اللَّهِ﴾",
      "وَقَوْلُهُ: ﴿قُلْ إِنْ كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ﴾ إِلَى قَوْلِهِ: ﴿أَحَبَّ إِلَيْكُمْ مِنَ اللَّهِ وَرَسُولِهِ﴾ الآيَةَ.",
      "عَنْ أَنَسٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ، وَوَالِدِهِ، وَالنَّاسِ أَجْمَعِينَ» أَخْرَجَاهُ.",
      "وَلَهُمَا: عَنْهُ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «ثَلَاثٌ مَنْ كُنَّ فِيهِ؛ وَجَدَ حَلَاوَةَ الإِيمَانِ: أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ، وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ، كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ».",
      "وَفِي رِوَايَةٍ: «لَا يَجِدُ أَحَدٌ حَلَاوَةَ الإِيمَانِ حَتَّى...» إِلَى آخِرِهِ.",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: «مَنْ أَحَبَّ فِي اللَّهِ، وَأَبْغَضَ فِي اللَّهِ، وَوَالَى فِي اللَّهِ، وَعَادَى فِي اللَّهِ؛ فَإِنَّمَا تُنَالُ وَلَايَةُ اللَّهِ بِذَلِكَ، وَلَنْ يَجِدَ عَبْدٌ طَعْمَ الإِيمَانِ - وَإِنْ كَثُرَتْ صَلَاتُهُ وَصَوْمُهُ - حَتَّى يَكُونَ كَذَلِكَ، وَقَدْ صَارَتْ عَامَّةُ مُؤَاخَاةِ النَّاسِ عَلَى أَمْرِ الدُّنْيَا، وَذَلِكَ لَا يُجْدِي عَلَى أَهْلِهِ شَيْئاً» رَوَاهُ ابْنُ جَرِيرٍ.",
      "وَقَالَ ابْنُ عَبَّاسٍ فِي قَوْلِهِ: «﴿وَتَقَطَّعَتْ بِهِمُ الأَسْبَابُ﴾؛ قَالَ: الْمَوَدَّةُ»."
    ]},
    { title: "[٣٢] باب قول الله تعالى: ﴿إنما ذلكم الشيطان يخوف أولياءه﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿إِنَّمَا ذَلِكُمُ الشَّيْطَانُ يُخَوِّفُ أَوْلِيَاءَهُ فَلَا تَخَافُوهُمْ وَخَافُونِ إِنْ كُنْتُمْ مُؤْمِنِينَ﴾",
      "وَقَوْلُهُ: ﴿إِنَّمَا يَعْمُرُ مَسَاجِدَ اللَّهِ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الآخِرِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ وَلَمْ يَخْشَ إِلَّا اللَّهَ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿وَمِنَ النَّاسِ مَنْ يَقُولُ آمَنَّا بِاللَّهِ فَإِذَا أُوذِيَ فِي اللَّهِ جَعَلَ فِتْنَةَ النَّاسِ كَعَذَابِ اللَّهِ﴾ الآيَةَ.",
      "عَنْ أَبِي سَعِيدٍ رضي الله عنه مَرْفُوعاً: «إِنَّ مِنْ ضَعْفِ الْيَقِينِ: أَنْ تُرْضِيَ النَّاسَ بِسَخَطِ اللَّهِ، وَأَنْ تَحْمَدَهُمْ عَلَى رِزْقِ اللَّهِ، وَأَنْ تَذُمَّهُمْ عَلَى مَا لَمْ يُؤْتِكَ اللَّهُ؛ إِنَّ رِزْقَ اللَّهِ لَا يَجُرُّهُ حِرْصُ حَرِيصٍ، وَلَا يَرُدُّهُ كَرَاهِيَةُ كَارِهٍ».",
      "وَعَنْ عَائِشَةَ رضي الله عنها أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنِ الْتَمَسَ رِضَا اللَّهِ بِسَخَطِ النَّاسِ؛ رَضِيَ اللَّهُ عَنْهُ، وَأَرْضَى عَنْهُ النَّاسَ.",
      "وَمَنِ الْتَمَسَ رِضَا النَّاسِ بِسَخَطِ اللَّهِ؛ سَخِطَ اللَّهُ عَلَيْهِ، وَأَسْخَطَ عَلَيْهِ النَّاسَ» رَوَاهُ ابْنُ حِبَّانَ فِي «صَحِيحِهِ»."
    ]},
    { title: "[٣٣] باب قول الله تعالى: ﴿وعلى الله فتوكلوا إن كنتم مؤمنين﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ عَزَّ وَجَلَّ: ﴿وَعَلَى اللَّهِ فَتَوَكَّلُوا إِنْ كُنْتُمْ مُؤْمِنِينَ﴾",
      "وَقَوْلُهُ: ﴿إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ﴾ الآيَةَ.",
      "وَقَوْلُهُ: ﴿يَا أَيُّهَا النَّبِيُّ حَسْبُكَ اللَّهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ﴾.",
      "وَقَوْلُهُ: ﴿وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ﴾.",
      "عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: «﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾؛ قَالَهَا إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ ﷺ حِينَ قَالُوا: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَاناً﴾ الآيَةَ» رَوَاهُ الْبُخَارِيُّ."
    ]},
    { title: "[٣٤] باب قول الله تعالى: ﴿أفأمنوا مكر الله﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿أَفَأَمِنُوا مَكْرَ اللَّهِ فَلَا يَأْمَنُ مَكْرَ اللَّهِ إِلَّا الْقَوْمُ الْخَاسِرُونَ﴾",
      "وَقَوْلُهُ: ﴿قَالَ وَمَنْ يَقْنَطُ مِنْ رَحْمَةِ رَبِّهِ إِلَّا الضَّالُّونَ﴾.",
      "عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: «أَنَّ رَسُولَ اللَّهِ ﷺ سُئِلَ عَنِ الْكَبَائِرِ؟ فَقَالَ: الشِّرْكُ بِاللَّهِ، وَالْيَأْسُ مِنْ رَوْحِ اللَّهِ، وَالأَمْنُ مِنْ مَكْرِ اللَّهِ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه قَالَ: «أَكْبَرُ الْكَبَائِرِ: الإِشْرَاكُ بِاللَّهِ، وَالأَمْنُ مِنْ مَكْرِ اللَّهِ، وَالْقُنُوطُ مِنْ رَحْمَةِ اللَّهِ، وَالْيَأْسُ مِنْ رَوْحِ اللَّهِ» رَوَاهُ عَبْدُ الرَّزَّاقِ."
    ]},
    { title: "[٣٥] باب من الإيمان بالله الصبر على أقدار الله", paras: [
      "#بَابٌ: مِنَ الإِيمَانِ بِاللَّهِ الصَّبْرُ عَلَى أَقْدَارِ اللَّهِ",
      "وَقَوْلُهُ تَعَالَى: ﴿وَمَنْ يُؤْمِنْ بِاللَّهِ يَهْدِ قَلْبَهُ﴾.",
      "قَالَ عَلْقَمَةُ: «هُوَ الرَّجُلُ تُصِيبُهُ الْمُصِيبَةُ، فَيَعْلَمُ أَنَّهَا مِنْ عِنْدِ اللَّهِ؛ فَيَرْضَى وَيُسَلِّمُ».",
      "وَفِي «صَحِيحِ مُسْلِمٍ»: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «اثْنَتَانِ فِي النَّاسِ هُمَا بِهِمْ كُفْرٌ: الطَّعْنُ فِي النَّسَبِ، وَالنِّيَاحَةُ عَلَى الْمَيِّتِ».",
      "وَلَهُمَا: عَنِ ابْنِ مَسْعُودٍ رضي الله عنه مَرْفُوعاً: «لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ، وَشَقَّ الْجُيُوبَ، وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ».",
      "وَعَنْ أَنَسٍ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «إِذَا أَرَادَ اللَّهُ بِعَبْدِهِ الْخَيْرَ؛ عَجَّلَ لَهُ الْعُقُوبَةَ فِي الدُّنْيَا، وَإِذَا أَرَادَ بِعَبْدِهِ الشَّرَّ؛ أَمْسَكَ عَنْهُ بِذَنْبِهِ، حَتَّى يُوَافِيَ بِهِ يَوْمَ الْقِيَامَةِ».",
      "وَقَالَ النَّبِيُّ ﷺ: «إِنَّ عِظَمَ الْجَزَاءِ مَعَ عِظَمِ الْبَلَاءِ، وَإِنَّ اللَّهَ تَعَالَى إِذَا أَحَبَّ قَوْماً ابْتَلَاهُمْ، فَمَنْ رَضِيَ فَلَهُ الرِّضَا، وَمَنْ سَخِطَ فَلَهُ السُّخْطُ» حَسَّنَهُ التِّرْمِذِيُّ."
    ]},
    { title: "[٣٦] باب ما جاء في الرياء", paras: [
      "#بَابُ مَا جَاءَ فِي الرِّيَاءِ",
      "وَقَوْلُهُ تَعَالَى: ﴿قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾ الآيَةَ.",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «قَالَ اللَّهُ تَعَالَى: أَنَا أَغْنَى الشُّرَكَاءِ عَنِ الشِّرْكِ، مَنْ عَمِلَ عَمَلاً أَشْرَكَ فِيهِ مَعِي غَيْرِي؛ تَرَكْتُهُ وَشِرْكَهُ» رَوَاهُ مُسْلِمٌ.",
      "وَعَنْ أَبِي سَعِيدٍ رضي الله عنه مَرْفُوعاً: «أَلَا أُخْبِرُكُمْ بِمَا هُوَ أَخْوَفُ عَلَيْكُمْ عِنْدِي مِنَ الْمَسِيحِ الدَّجَّالِ؟ قُلْنَا: بَلَى، قَالَ: الشِّرْكُ الْخَفِيُّ - يَقُومُ الرَّجُلُ فَيُصَلِّي فَيُزَيِّنُ صَلَاتَهُ؛ لِمَا يَرَى مِنْ نَظَرِ رَجُلٍ -» رَوَاهُ أَحْمَدُ."
    ]},
    { title: "[٣٧] باب من الشرك إرادة الإنسان بعمله الدنيا", paras: [
      "#بَابٌ: مِنَ الشِّرْكِ إِرَادَةُ الإِنْسَانِ بِعَمَلِهِ الدُّنْيَا",
      "وَقَوْلُهُ تَعَالَى: ﴿مَنْ كَانَ يُرِيدُ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَالَهُمْ فِيهَا﴾ الآيَتَيْنِ.",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «تَعِسَ عَبْدُ الدِّينَارِ، تَعِسَ عَبْدُ الدِّرْهَمِ، تَعِسَ عَبْدُ الْخَمِيصَةِ، تَعِسَ عَبْدُ الْخَمِيلَةِ، إِنْ أُعْطِيَ رَضِيَ، وَإِنْ لَمْ يُعْطَ سَخِطَ، تَعِسَ وَانْتَكَسَ، وَإِذَا شِيكَ فَلَا انْتَقَشَ.",
      "طُوبَى لِعَبْدٍ آخِذٍ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ، أَشْعَثَ رَأْسُهُ، مُغْبَرَّةٍ قَدَمَاهُ، إِنْ كَانَ فِي الْحِرَاسَةِ كَانَ فِي الْحِرَاسَةِ، وَإِنْ كَانَ فِي السَّاقَةِ كَانَ فِي السَّاقَةِ، إِنِ اسْتَأْذَنَ لَمْ يُؤْذَنْ لَهُ، وَإِنْ شَفَعَ لَمْ يُشَفَّعْ»."
    ]},
    { title: "[٣٨] باب من أطاع العلماء والأمراء في تحريم ما أحل الله", paras: [
      "#بَابُ مَنْ أَطَاعَ الْعُلَمَاءَ وَالأُمَرَاءَ فِي تَحْرِيمِ مَا أَحَلَّ اللَّهُ، وَتَحْلِيلِ مَا حَرَّمَهُ؛ فَقَدِ اتَّخَذَهُمْ أَرْبَاباً",
      "وَقَالَ ابْنُ عَبَّاسٍ رضي الله عنهما: «يُوشِكُ أَنْ تَنْزِلَ عَلَيْكُمْ حِجَارَةٌ مِنَ السَّمَاءِ، أَقُولُ: قَالَ رَسُولُ اللَّهِ ﷺ، وَتَقُولُونَ: قَالَ أَبُو بَكْرٍ وَعُمَرُ؟!».",
      "وَقَالَ أَحْمَدُ بْنُ حَنْبَلٍ: «عَجِبْتُ لِقَوْمٍ عَرَفُوا الإِسْنَادَ وَصِحَّتَهُ يَذْهَبُونَ إِلَى رَأْيِ سُفْيَانَ، وَاللَّهُ تَعَالَى يَقُولُ: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ﴾ الآيَةَ، أَتَدْرِي مَا الْفِتْنَةُ؟ الْفِتْنَةُ: الشِّرْكُ؛ لَعَلَّهُ إِذَا رَدَّ بَعْضَ قَوْلِهِ أَنْ يَقَعَ فِي قَلْبِهِ شَيْءٌ مِنَ الزَّيْغِ؛ فَيَهْلِكَ».",
      "عَنْ عَدِيِّ بْنِ حَاتِمٍ رضي الله عنه: «أَنَّهُ سَمِعَ النَّبِيَّ ﷺ يَقْرَأُ هَذِهِ الآيَةَ: ﴿اتَّخَذُوا أَحْبَارَهُمْ وَرُهْبَانَهُمْ أَرْبَاباً مِنْ دُونِ اللَّهِ﴾ الآيَةَ، فَقُلْتُ لَهُ: إِنَّا لَسْنَا نَعْبُدُهُمْ، قَالَ: أَلَيْسَ يُحَرِّمُونَ مَا أَحَلَّ اللَّهُ فَتُحَرِّمُونَهُ، وَيُحِلُّونَ مَا حَرَّمَ اللَّهُ فَتُحِلُّونَهُ؟ فَقُلْتُ: بَلَى، قَالَ: فَتِلْكَ عِبَادَتُهُمْ» رَوَاهُ أَحْمَدُ، وَالتِّرْمِذِيُّ وَحَسَّنَهُ."
    ]},
    { title: "[٣٩] باب قول الله تعالى: ﴿ألم تر إلى الذين يزعمون أنهم آمنوا﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنْزِلَ إِلَيْكَ وَمَا أُنْزِلَ مِنْ قَبْلِكَ يُرِيدُونَ أَنْ يَتَحَاكَمُوا إِلَى الطَّاغُوتِ وَقَدْ أُمِرُوا أَنْ يَكْفُرُوا بِهِ﴾ الآيَاتِ",
      "وَقَوْلُهُ: ﴿وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا فِي الأَرْضِ قَالُوا إِنَّمَا نَحْنُ مُصْلِحُونَ﴾.",
      "وَقَوْلُهُ: ﴿وَلَا تُفْسِدُوا فِي الأَرْضِ بَعْدَ إِصْلَاحِهَا﴾.",
      "وَقَوْلُهُ: ﴿أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْماً لِقَوْمٍ يُوقِنُونَ﴾.",
      "عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رضي الله عنهما أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعاً لِمَا جِئْتُ بِهِ» قَالَ النَّوَوِيُّ: «حَدِيثٌ صَحِيحٌ، رُوِّينَاهُ فِي كِتَابِ الْحُجَّةِ بِإِسْنَادٍ صَحِيحٍ».",
      "وَقَالَ الشَّعْبِيُّ: «كَانَ بَيْنَ رَجُلٍ مِنَ الْمُنَافِقِينَ وَرَجُلٍ مِنَ الْيَهُودِ خُصُومَةٌ، فَقَالَ الْيَهُودِيُّ: نَتَحَاكَمُ إِلَى مُحَمَّدٍ - عَرَفَ أَنَّهُ لَا يَأْخُذُ الرِّشْوَةَ -، وَقَالَ الْمُنَافِقُ: نَتَحَاكَمُ إِلَى الْيَهُودِ - لِعِلْمِهِ أَنَّهُمْ يَأْخُذُونَ الرِّشْوَةَ -.",
      "فَاتَّفَقَا عَلَى أَنْ يَأْتِيَا كَاهِناً فِي جُهَيْنَةَ؛ فَيَتَحَاكَمَا إِلَيْهِ؛ فَنَزَلَتْ: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ أَنَّهُمْ آمَنُوا بِمَا أُنْزِلَ إِلَيْكَ﴾ الآيَةَ».",
      "وَقِيلَ: «نَزَلَتْ فِي رَجُلَيْنِ اخْتَصَمَا، فَقَالَ أَحَدُهُمَا: نَتَرَافَعُ إِلَى النَّبِيِّ ﷺ، وَقَالَ الآخَرُ: إِلَى كَعْبِ بْنِ الأَشْرَفِ.",
      "ثُمَّ تَرَافَعَا إِلَى عُمَرَ رضي الله عنه، فَذَكَرَ لَهُ أَحَدُهُمَا الْقِصَّةَ، فَقَالَ لِلَّذِي لَمْ يَرْضَ بِرَسُولِ اللَّهِ ﷺ: أَكَذَلِكَ؟! قَالَ: نَعَمْ، فَضَرَبَهُ بِالسَّيْفِ؛ فَقَتَلَهُ»."
    ]},
    { title: "[٤٠] باب من جحد شيئاً من الأسماء والصفات", paras: [
      "#بَابُ مَنْ جَحَدَ شَيْئاً مِنَ الأَسْمَاءِ وَالصِّفَاتِ",
      "وَقَوْلُ اللَّهِ عَزَّ وَجَلَّ: ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ﴾ الآيَةَ.",
      "فِي «صَحِيحِ الْبُخَارِيِّ»: عَنْ عَلِيٍّ رضي الله عنه قَالَ: «حَدِّثُوا النَّاسَ بِمَا يَعْرِفُونَ، أَتُرِيدُونَ أَنْ يُكَذَّبَ اللَّهُ وَرَسُولُهُ؟!».",
      "وَرَوَى عَبْدُ الرَّزَّاقِ: عَنْ مَعْمَرٍ، عَنِ ابْنِ طَاوُسٍ، عَنْ أَبِيهِ، عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: «أَنَّهُ رَأَى رَجُلاً انْتَفَضَ لَمَّا سَمِعَ حَدِيثاً عَنِ النَّبِيِّ ﷺ فِي الصِّفَاتِ؛ اسْتِنْكَاراً لِذَلِكَ، فَقَالَ: مَا فَرَقُ هَؤُلَاءِ؟ يَجِدُونَ رِقَّةً عِنْدَ مُحْكَمِهِ، وَيَهْلِكُونَ عِنْدَ مُتَشَابِهِهِ» انْتَهَى.",
      "وَلَمَّا سَمِعَتْ قُرَيْشٌ رَسُولَ اللَّهِ ﷺ يَذْكُرُ الرَّحْمَنَ؛ أَنْكَرُوا ذَلِكَ؛ فَأَنْزَلَ اللَّهُ فِيهِمْ: ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ﴾."
    ]},
    { title: "[٤١] باب قول الله تعالى: ﴿يعرفون نعمت الله ثم ينكرونها﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ عَزَّ وَجَلَّ: ﴿يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَهَا﴾",
      "قَالَ مُجَاهِدٌ مَا مَعْنَاهُ: «هُوَ قَوْلُ الرَّجُلِ: هَذَا مَالِي، وَرِثْتُهُ عَنْ آبَائِي».",
      "وَقَالَ عَوْنُ بْنُ عَبْدِ اللَّهِ: «يَقُولُونَ: لَوْلَا فُلَانٌ، لَمْ يَكُنْ كَذَا».",
      "وَقَالَ ابْنُ قُتَيْبَةَ: «يَقُولُونَ: هَذَا بِشَفَاعَةِ آلِهَتِنَا».",
      "وَقَالَ أَبُو الْعَبَّاسِ - بَعْدَ حَدِيثِ زَيْدِ بْنِ خَالِدٍ رضي الله عنه الَّذِي فِيهِ: «إِنَّ اللَّهَ تَعَالَى قَالَ: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ...» الْحَدِيثَ، وَقَدْ تَقَدَّمَ -: «وَهَذَا كَثِيرٌ فِي الْكِتَابِ وَالسُّنَّةِ، يَذُمُّ سُبْحَانَهُ مَنْ يُضِيفُ إِنْعَامَهُ إِلَى غَيْرِهِ وَيُشْرِكُ بِهِ. قَالَ بَعْضُ السَّلَفِ: هُوَ كَقَوْلِهِمْ: كَانَتِ الرِّيحُ طَيِّبَةً، وَالْمَلَّاحُ حَاذِقاً.",
      "وَنَحْوِ هَذَا مِمَّا هُوَ جَارٍ عَلَى أَلْسِنَةِ كَثِيرٍ»."
    ]},
    { title: "[٤٢] باب قول الله تعالى: ﴿فلا تجعلوا لله أنداداً وأنتم تعلمون﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿فَلَا تَجْعَلُوا لِلَّهِ أَنْدَاداً وَأَنْتُمْ تَعْلَمُونَ﴾",
      "قَالَ ابْنُ عَبَّاسٍ رضي الله عنهما فِي الآيَةِ: «الأَنْدَادُ: هُوَ الشِّرْكُ، أَخْفَى مِنْ دَبِيبِ النَّمْلِ عَلَى صَفَاةٍ سَوْدَاءَ فِي ظُلْمَةِ اللَّيْلِ، وَهُوَ أَنْ تَقُولَ: وَاللَّهِ وَحَيَاتِكَ يَا فُلَانَةُ وَحَيَاتِي.",
      "وَتَقُولَ: لَوْلَا كُلَيْبَةُ هَذَا لَأَتَانَا اللُّصُوصُ، وَلَوْلَا الْبَطُّ فِي الدَّارِ لَأَتَى اللُّصُوصُ.",
      "وَقَوْلُ الرَّجُلِ لِصَاحِبِهِ: مَا شَاءَ اللَّهُ وَشِئْتَ.",
      "وَقَوْلُ الرَّجُلِ: لَوْلَا اللَّهُ وَفُلَانٌ، لَا تَجْعَلْ فِيهَا فُلَانٌ، هَذَا كُلُّهُ بِهِ شِرْكٌ» رَوَاهُ ابْنُ أَبِي حَاتِمٍ.",
      "وَعَنْ عُمَرَ بْنِ الْخَطَّابِ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ حَلَفَ بِغَيْرِ اللَّهِ؛ فَقَدْ كَفَرَ، أَوْ أَشْرَكَ» رَوَاهُ التِّرْمِذِيُّ وَحَسَّنَهُ، وَصَحَّحَهُ الْحَاكِمُ.",
      "وَقَالَ ابْنُ مَسْعُودٍ رضي الله عنه: «لَأَنْ أَحْلِفَ بِاللَّهِ كَاذِباً، أَحَبُّ إِلَيَّ مِنْ أَنْ أَحْلِفَ بِغَيْرِهِ صَادِقاً».",
      "وَعَنْ حُذَيْفَةَ رضي الله عنه عَنِ النَّبِيِّ ﷺ قَالَ: «لَا تَقُولُوا: مَا شَاءَ اللَّهُ وَشَاءَ فُلَانٌ، وَلَكِنْ قُولُوا: مَا شَاءَ اللَّهُ ثُمَّ شَاءَ فُلَانٌ» رَوَاهُ أَبُو دَاوُدَ بِسَنَدٍ صَحِيحٍ.",
      "وَعَنْ إِبْرَاهِيمَ النَّخَعِيِّ: «أَنَّهُ يَكْرَهُ أَنْ يَقُولَ الرَّجُلُ: أَعُوذُ بِاللَّهِ وَبِكَ، وَيُجَوِّزُ أَنْ يَقُولَ: بِاللَّهِ ثُمَّ بِكَ، وَيَقُولُ: لَوْلَا اللَّهُ ثُمَّ فُلَانٌ، وَلَا تَقُولُوا: لَوْلَا اللَّهُ وَفُلَانٌ»."
    ]},
    { title: "[٤٣] باب ما جاء فيمن لم يقنع بالحلف بالله", paras: [
      "#بَابُ مَا جَاءَ فِيمَنْ لَمْ يَقْنَعْ بِالْحَلِفِ بِاللَّهِ",
      "عَنِ ابْنِ عُمَرَ رضي الله عنهما أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا تَحْلِفُوا بِآبَائِكُمْ، مَنْ حَلَفَ بِاللَّهِ فَلْيَصْدُقْ، وَمَنْ حُلِفَ لَهُ بِاللَّهِ فَلْيَرْضَ، وَمَنْ لَمْ يَرْضَ فَلَيْسَ مِنَ اللَّهِ» رَوَاهُ ابْنُ مَاجَهْ بِسَنَدٍ حَسَنٍ."
    ]},
    { title: "[٤٤] باب قول: ما شاء الله وشئت", paras: [
      "#بَابُ قَوْلِ: مَا شَاءَ اللَّهُ وَشِئْتَ",
      "عَنْ قُتَيْلَةَ رضي الله عنها: «أَنَّ يَهُودِيّاً أَتَى النَّبِيَّ ﷺ، فَقَالَ: إِنَّكُمْ تُشْرِكُونَ؛ تَقُولُونَ: مَا شَاءَ اللَّهُ وَشِئْتَ، وَتَقُولُونَ: وَالْكَعْبَةِ.",
      "فَأَمَرَهُمُ النَّبِيُّ ﷺ إِذَا أَرَادُوا أَنْ يَحْلِفُوا أَنْ يَقُولُوا: وَرَبِّ الْكَعْبَةِ، وَأَنْ يَقُولُوا: مَا شَاءَ اللَّهُ ثُمَّ شِئْتَ» رَوَاهُ النَّسَائِيُّ وَصَحَّحَهُ.",
      "وَلَهُ أَيْضاً: عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: «أَنَّ رَجُلاً قَالَ لِلنَّبِيِّ ﷺ: مَا شَاءَ اللَّهُ وَشِئْتَ، فَقَالَ: أَجَعَلْتَنِي لِلَّهِ نِدّاً؟! قُلْ: مَا شَاءَ اللَّهُ وَحْدَهُ».",
      "وَلِابْنِ مَاجَهْ: عَنِ الطُّفَيْلِ رضي الله عنه - أَخِي عَائِشَةَ رضي الله عنها لِأُمِّهَا - قَالَ: «رَأَيْتُ كَأَنِّي أَتَيْتُ عَلَى نَفَرٍ مِنَ الْيَهُودِ، فَقُلْتُ: إِنَّكُمْ لَأَنْتُمُ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ: عُزَيْرٌ ابْنُ اللَّهِ، قَالُوا: وَإِنَّكُمْ لَأَنْتُمُ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ: مَا شَاءَ اللَّهُ وَشَاءَ مُحَمَّدٌ.",
      "ثُمَّ مَرَرْتُ بِنَفَرٍ مِنَ النَّصَارَى، فَقُلْتُ: إِنَّكُمْ لَأَنْتُمُ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ: الْمَسِيحُ ابْنُ اللَّهِ، قَالُوا: وَإِنَّكُمْ لَأَنْتُمُ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ: مَا شَاءَ اللَّهُ وَشَاءَ مُحَمَّدٌ.",
      "فَلَمَّا أَصْبَحْتُ؛ أَخْبَرْتُ بِهَا مَنْ أَخْبَرْتُ، ثُمَّ أَتَيْتُ النَّبِيَّ ﷺ، فَأَخْبَرْتُهُ، فَقَالَ: هَلْ أَخْبَرْتَ بِهَا أَحَداً؟ قُلْتُ: نَعَمْ.",
      "قَالَ: فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ؛ فَإِنَّ طُفَيْلاً رَأَى رُؤْيَا أَخْبَرَ بِهَا مَنْ أَخْبَرَ مِنْكُمْ، وَإِنَّكُمْ قُلْتُمْ كَلِمَةً كَانَ يَمْنَعُنِي كَذَا وَكَذَا أَنْ أَنْهَاكُمْ عَنْهَا؛ فَلَا تَقُولُوا: مَا شَاءَ اللَّهُ وَشَاءَ مُحَمَّدٌ، وَلَكِنْ قُولُوا: مَا شَاءَ اللَّهُ وَحْدَهُ»."
    ]},
    { title: "[٤٥] باب من سب الدهر فقد آذى الله", paras: [
      "#بَابُ مَنْ سَبَّ الدَّهْرَ؛ فَقَدْ آذَى اللَّهَ",
      "وَقَوْلُ اللَّهِ: ﴿وَقَالُوا مَا هِيَ إِلَّا حَيَاتُنَا الدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَا إِلَّا الدَّهْرُ﴾ الآيَةَ.",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ ﷺ قَالَ: «قَالَ اللَّهُ تَعَالَى: يُؤْذِينِي ابْنُ آدَمَ، يَسُبُّ الدَّهْرَ، وَأَنَا الدَّهْرُ؛ أُقَلِّبُ اللَّيْلَ وَالنَّهَارَ».",
      "وَفِي رِوَايَةٍ: «لَا تَسُبُّوا الدَّهْرَ؛ فَإِنَّ اللَّهَ هُوَ الدَّهْرُ»."
    ]},
    { title: "[٤٦] باب التسمي بقاضي القضاة ونحوه", paras: [
      "#بَابُ التَّسَمِّي بِقَاضِي الْقُضَاةِ وَنَحْوِهِ",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ أَخْنَعَ اسْمٍ عِنْدَ اللَّهِ: رَجُلٌ يُسَمَّى مَلِكَ الأَمْلَاكِ؛ لَا مَالِكَ إِلَّا اللَّهُ».",
      "قَالَ سُفْيَانُ: «مِثْلُ: شَاهَانْ شَاهْ».",
      "وَفِي رِوَايَةٍ: «أَغْيَظُ رَجُلٍ عَلَى اللَّهِ يَوْمَ الْقِيَامَةِ، وَأَخْبَثُهُ».",
      "قَوْلُهُ: «أَخْنَعَ» يَعْنِي: أَوْضَعَ."
    ]},
    { title: "[٤٧] باب احترام أسماء الله تعالى وتغيير الاسم لأجل ذلك", paras: [
      "#بَابُ احْتِرَامِ أَسْمَاءِ اللَّهِ تَعَالَى، وَتَغْيِيرِ الِاسْمِ لِأَجْلِ ذَلِكَ",
      "عَنْ أَبِي شُرَيْحٍ رضي الله عنه: أَنَّهُ كَانَ يُكْنَى أَبَا الْحَكَمِ، فَقَالَ لَهُ النَّبِيُّ ﷺ: «إِنَّ اللَّهَ هُوَ الْحَكَمُ، وَإِلَيْهِ الْحُكْمُ، فَقَالَ: إِنَّ قَوْمِي إِذَا اخْتَلَفُوا فِي شَيْءٍ أَتَوْنِي، فَحَكَمْتُ بَيْنَهُمْ، فَرَضِيَ كِلَا الْفَرِيقَيْنِ، فَقَالَ: مَا أَحْسَنَ هَذَا! فَمَا لَكَ مِنَ الْوَلَدِ؟ قُلْتُ: شُرَيْحٌ، وَمُسْلِمٌ، وَعَبْدُ اللَّهِ، قَالَ: فَمَنْ أَكْبَرُهُمْ؟ قُلْتُ: شُرَيْحٌ، قَالَ: فَأَنْتَ أَبُو شُرَيْحٍ» رَوَاهُ أَبُو دَاوُدَ، وَغَيْرُهُ."
    ]},
    { title: "[٤٨] باب من هزل بشيء فيه ذكر الله أو القرآن أو الرسول", paras: [
      "#بَابُ مَنْ هَزَلَ بِشَيْءٍ فِيهِ ذِكْرُ اللَّهِ، أَوِ الْقُرْآنِ، أَوِ الرَّسُولِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَلَئِنْ سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ * لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ﴾.",
      "عَنِ ابْنِ عُمَرَ رضي الله عنهما، وَمُحَمَّدِ بْنِ كَعْبٍ، وَزَيْدِ بْنِ أَسْلَمَ، وَقَتَادَةَ - دَخَلَ حَدِيثُ بَعْضِهِمْ فِي بَعْضٍ -: «أَنَّهُ قَالَ رَجُلٌ فِي غَزْوَةِ تَبُوكَ: مَا رَأَيْنَا مِثْلَ قُرَّائِنَا هَؤُلَاءِ؛ أَرْغَبَ بُطُوناً، وَلَا أَكْذَبَ أَلْسُناً، وَلَا أَجْبَنَ عِنْدَ اللِّقَاءِ - يَعْنِي: رَسُولَ اللَّهِ ﷺ وَأَصْحَابَهُ الْقُرَّاءَ -.",
      "فَقَالَ لَهُ عَوْفُ بْنُ مَالِكٍ: كَذَبْتَ؛ وَلَكِنَّكَ مُنَافِقٌ، لَأُخْبِرَنَّ رَسُولَ اللَّهِ ﷺ، فَذَهَبَ عَوْفٌ إِلَى رَسُولِ اللَّهِ ﷺ لِيُخْبِرَهُ، فَوَجَدَ الْقُرْآنَ قَدْ سَبَقَهُ.",
      "فَجَاءَ ذَلِكَ الرَّجُلُ إِلَى رَسُولِ اللَّهِ ﷺ وَقَدِ ارْتَحَلَ وَرَكِبَ نَاقَتَهُ، فَقَالَ: يَا رَسُولَ اللَّهِ! إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ وَنَتَحَدَّثُ حَدِيثَ الرَّكْبِ؛ نَقْطَعُ بِهِ عَنَّا الطَّرِيقَ.",
      "قَالَ ابْنُ عُمَرَ: كَأَنِّي أَنْظُرُ إِلَيْهِ؛ مُتَعَلِّقاً بِنِسْعَةِ نَاقَةِ رَسُولِ اللَّهِ ﷺ، وَإِنَّ الْحِجَارَةَ تَنْكُبُ رِجْلَيْهِ، وَهُوَ يَقُولُ: ﴿إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ﴾، فَيَقُولُ لَهُ رَسُولُ اللَّهِ ﷺ: ﴿أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ﴾؛ مَا يَلْتَفِتُ إِلَيْهِ، وَمَا يَزِيدُهُ عَلَيْهِ»."
    ]},
    { title: "[٤٩] باب قول الله تعالى: ﴿ولئن أذقناه رحمة منا﴾", paras: [
      "#بَابُ مَا جَاءَ فِي قَوْلِ اللَّهِ تَعَالَى: ﴿وَلَئِنْ أَذَقْنَاهُ رَحْمَةً مِنَّا مِنْ بَعْدِ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ هَذَا لِي﴾ الآيَةَ",
      "قَالَ مُجَاهِدٌ: «هَذَا بِعَمَلِي، وَأَنَا مَحْقُوقٌ بِهِ».",
      "وَقَالَ ابْنُ عَبَّاسٍ: «يُرِيدُ: مِنْ عِنْدِي».",
      "وَقَوْلُهُ: ﴿قَالَ إِنَّمَا أُوتِيتُهُ عَلَى عِلْمٍ عِنْدِي﴾.",
      "قَالَ قَتَادَةُ: «عَلَى عِلْمٍ مِنِّي بِوُجُوهِ الْمَكَاسِبِ».",
      "وَقَالَ آخَرُونَ: «عَلَى عِلْمٍ مِنَ اللَّهِ أَنِّي لَهُ أَهْلٌ».",
      "وَهَذَا مَعْنَى قَوْلِ مُجَاهِدٍ: «أُوتِيتُهُ عَلَى شَرَفٍ».",
      "وَعَنْ أَبِي هُرَيْرَةَ رضي الله عنه: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ﷺ يَقُولُ: «إِنَّ ثَلَاثَةً مِنْ بَنِي إِسْرَائِيلَ: أَبْرَصَ، وَأَقْرَعَ، وَأَعْمَى، فَأَرَادَ اللَّهُ أَنْ يَبْتَلِيَهُمْ، فَبَعَثَ إِلَيْهِمْ مَلَكاً، فَأَتَى الأَبْرَصَ، فَقَالَ: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: لَوْنٌ حَسَنٌ، وَجِلْدٌ حَسَنٌ، وَيَذْهَبُ عَنِّي الَّذِي قَدْ قَذِرَنِي النَّاسُ.",
      "قَالَ: فَمَسَحَهُ، فَذَهَبَ عَنْهُ قَذَرُهُ، وَأُعْطِيَ لَوْناً حَسَناً، وَجِلْداً حَسَناً، قَالَ: فَأَيُّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الإِبِلُ أَوِ الْبَقَرُ - شَكَّ إِسْحَاقُ -، فَأُعْطِيَ نَاقَةً عُشَرَاءَ، وَقَالَ: بَارَكَ اللَّهُ لَكَ فِيهَا.",
      "قَالَ: فَأَتَى الأَقْرَعَ، فَقَالَ: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: شَعْرٌ حَسَنٌ، وَيَذْهَبُ عَنِّي الَّذِي قَدْ قَذِرَنِي النَّاسُ.",
      "قَالَ: فَمَسَحَهُ، فَذَهَبَ عَنْهُ، وَأُعْطِيَ شَعْراً حَسَناً، قَالَ: فَأَيُّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الْبَقَرُ أَوِ الإِبِلُ، فَأُعْطِيَ بَقَرَةً حَامِلاً، وَقَالَ: بَارَكَ اللَّهُ لَكَ فِيهَا.",
      "قَالَ: فَأَتَى الأَعْمَى، فَقَالَ: أَيُّ شَيْءٍ أَحَبُّ إِلَيْكَ؟ قَالَ: أَنْ يَرُدَّ اللَّهُ إِلَيَّ بَصَرِي، فَأُبْصِرَ بِهِ النَّاسَ.",
      "قَالَ: فَمَسَحَهُ، فَرَدَّ اللَّهُ إِلَيْهِ بَصَرَهُ، قَالَ: فَأَيُّ الْمَالِ أَحَبُّ إِلَيْكَ؟ قَالَ: الْغَنَمُ، فَأُعْطِيَ شَاةً وَالِداً.",
      "فَأُنْتِجَ هَذَانِ، وَوَلَّدَ هَذَا؛ فَكَانَ لِهَذَا وَادٍ مِنَ الإِبِلِ، وَلِهَذَا وَادٍ مِنَ الْبَقَرِ، وَلِهَذَا وَادٍ مِنَ الْغَنَمِ.",
      "قَالَ: ثُمَّ إِنَّهُ أَتَى الأَبْرَصَ فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ: رَجُلٌ مِسْكِينٌ، قَدِ انْقَطَعَتْ بِيَ الْحِبَالُ فِي سَفَرِي، فَلَا بَلَاغَ لِيَ الْيَوْمَ إِلَّا بِاللَّهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي أَعْطَاكَ اللَّوْنَ الْحَسَنَ، وَالْجِلْدَ الْحَسَنَ، وَالْمَالَ، بَعِيراً أَتَبَلَّغُ بِهِ فِي سَفَرِي، فَقَالَ: الْحُقُوقُ كَثِيرَةٌ.",
      "فَقَالَ لَهُ: كَأَنِّي أَعْرِفُكَ! أَلَمْ تَكُنْ أَبْرَصَ يَقْذَرُكَ النَّاسُ؛ فَقِيراً فَأَعْطَاكَ اللَّهُ؟!",
      "فَقَالَ: إِنَّمَا وَرِثْتُ هَذَا الْمَالَ كَابِراً عَنْ كَابِرٍ، فَقَالَ: إِنْ كُنْتَ كَاذِباً؛ فَصَيَّرَكَ اللَّهُ إِلَى مَا كُنْتَ.",
      "قَالَ: وَأَتَى الأَقْرَعَ فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ لَهُ مِثْلَ مَا قَالَ لِهَذَا، وَرَدَّ عَلَيْهِ مِثْلَ مَا رَدَّ عَلَيْهِ هَذَا، فَقَالَ: إِنْ كُنْتَ كَاذِباً؛ فَصَيَّرَكَ اللَّهُ إِلَى مَا كُنْتَ.",
      "قَالَ: وَأَتَى الأَعْمَى فِي صُورَتِهِ وَهَيْئَتِهِ، فَقَالَ: رَجُلٌ مِسْكِينٌ وَابْنُ سَبِيلٍ، انْقَطَعَتْ بِيَ الْحِبَالُ فِي سَفَرِي؛ فَلَا بَلَاغَ لِيَ الْيَوْمَ إِلَّا بِاللَّهِ ثُمَّ بِكَ، أَسْأَلُكَ بِالَّذِي رَدَّ عَلَيْكَ بَصَرَكَ، شَاةً أَتَبَلَّغُ بِهَا فِي سَفَرِي.",
      "فَقَالَ: قَدْ كُنْتُ أَعْمَى فَرَدَّ اللَّهُ إِلَيَّ بَصَرِي، فَخُذْ مَا شِئْتَ، وَدَعْ مَا شِئْتَ، فَوَاللَّهِ لَا أَجْهَدُكَ الْيَوْمَ بِشَيْءٍ أَخَذْتَهُ لِلَّهِ.",
      "فَقَالَ: أَمْسِكْ مَالَكَ؛ فَإِنَّمَا ابْتُلِيتُمْ؛ فَقَدْ رُضِيَ عَنْكَ، وَسُخِطَ عَلَى صَاحِبَيْكَ» أَخْرَجَاهُ."
    ]},
    { title: "[٥٠] باب قول الله تعالى: ﴿فلما آتاهما صالحاً جعلا له شركاء﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿فَلَمَّا آتَاهُمَا صَالِحاً جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا﴾ الآيَةَ",
      "قَالَ ابْنُ حَزْمٍ: «اتَّفَقُوا عَلَى تَحْرِيمِ كُلِّ اسْمٍ مُعَبَّدٍ لِغَيْرِ اللَّهِ؛ كَعَبْدِ عَمْرٍو، وَعَبْدِ الْكَعْبَةِ، وَمَا أَشْبَهَ ذَلِكَ، حَاشَا عَبْدَ الْمُطَّلِبِ».",
      "وَعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما فِي الآيَةِ؛ قَالَ: «لَمَّا تَغَشَّاهَا آدَمُ؛ حَمَلَتْ، فَأَتَاهُمَا إِبْلِيسُ، فَقَالَ: إِنِّي صَاحِبُكُمَا الَّذِي أَخْرَجْتُكُمَا مِنَ الْجَنَّةِ، لَتُطِيعُنَّنِي أَوْ لَأَجْعَلَنَّ لَهُ قَرْنَيْ أَيِّلٍ، فَيَخْرُجُ مِنْ بَطْنِكِ، فَيَشُقُّهُ، وَلَأَفْعَلَنَّ، وَلَأَفْعَلَنَّ - يُخَوِّفُهُمَا -، سَمِّيَاهُ عَبْدَ الْحَارِثِ، فَأَبَيَا أَنْ يُطِيعَاهُ، فَخَرَجَ مَيِّتاً.",
      "ثُمَّ حَمَلَتْ، فَأَتَاهُمَا فَقَالَ مِثْلَ قَوْلِهِ، فَأَبَيَا أَنْ يُطِيعَاهُ، فَخَرَجَ مَيِّتاً.",
      "ثُمَّ حَمَلَتْ، فَأَتَاهُمَا فَذَكَرَ لَهُمَا، فَأَدْرَكَهُمَا حُبُّ الْوَلَدِ، فَسَمَّيَاهُ عَبْدَ الْحَارِثِ؛ فَذَلِكَ قَوْلُهُ: ﴿جَعَلَا لَهُ شُرَكَاءَ فِيمَا آتَاهُمَا﴾» رَوَاهُ ابْنُ أَبِي حَاتِمٍ.",
      "وَلَهُ بِسَنَدٍ صَحِيحٍ: عَنْ قَتَادَةَ؛ قَالَ: «شُرَكَاءَ فِي طَاعَتِهِ، وَلَمْ يَكُنْ فِي عِبَادَتِهِ».",
      "وَلَهُ بِسَنَدٍ صَحِيحٍ: عَنْ مُجَاهِدٍ فِي قَوْلِهِ: ﴿لَئِنْ آتَيْتَنَا صَالِحاً﴾؛ قَالَ: «أَشْفَقَا أَلَّا يَكُونَ إِنْسَاناً».",
      "وَذَكَرَ مَعْنَاهُ: عَنِ الْحَسَنِ، وَسَعِيدٍ، وَغَيْرِهِمَا."
    ]},
    { title: "[٥١] باب قول الله تعالى: ﴿ولله الأسماء الحسنى فادعوه بها﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمَائِهِ﴾ الآيَةَ",
      "ذَكَرَ ابْنُ أَبِي حَاتِمٍ: عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما: «﴿يُلْحِدُونَ فِي أَسْمَائِهِ﴾: يُشْرِكُونَ».",
      "وَعَنْهُ: «سَمَّوُا اللَّاتَ مِنَ الإِلَهِ، وَالْعُزَّى مِنَ الْعَزِيزِ».",
      "وَعَنِ الأَعْمَشِ: «يُدْخِلُونَ فِيهَا مَا لَيْسَ مِنْهَا»."
    ]},
    { title: "[٥٢] باب لا يقال: السلام على الله", paras: [
      "#بَابٌ: لَا يُقَالُ: السَّلَامُ عَلَى اللَّهِ",
      "فِي الصَّحِيحِ: عَنِ ابْنِ مَسْعُودٍ رضي الله عنه قَالَ: «كُنَّا إِذَا كُنَّا مَعَ النَّبِيِّ ﷺ فِي الصَّلَاةِ؛ قُلْنَا: السَّلَامُ عَلَى اللَّهِ مِنْ عِبَادِهِ، السَّلَامُ عَلَى فُلَانٍ، فَقَالَ النَّبِيُّ ﷺ: لَا تَقُولُوا: السَّلَامُ عَلَى اللَّهِ؛ فَإِنَّ اللَّهَ هُوَ السَّلَامُ»."
    ]},
    { title: "[٥٣] باب قول: اللهم اغفر لي إن شئت", paras: [
      "#بَابُ قَوْلِ: اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا يَقُولَنَّ أَحَدُكُمْ: اللَّهُمَّ اغْفِرْ لِي إِنْ شِئْتَ، اللَّهُمَّ ارْحَمْنِي إِنْ شِئْتَ، لِيَعْزِمِ الْمَسْأَلَةَ؛ فَإِنَّ اللَّهَ لَا مُكْرِهَ لَهُ».",
      "وَلِمُسْلِمٍ: «وَلْيُعَظِّمِ الرَّغْبَةَ؛ فَإِنَّ اللَّهَ لَا يَتَعَاظَمُهُ شَيْءٌ أَعْطَاهُ»."
    ]},
    { title: "[٥٤] باب لا يقول: عبدي وأمتي", paras: [
      "#بَابٌ: لَا يَقُولُ: عَبْدِي وَأَمَتِي",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَا يَقُلْ أَحَدُكُمْ: أَطْعِمْ رَبَّكَ، وَضِّئْ رَبَّكَ، وَلْيَقُلْ: سَيِّدِي وَمَوْلَايَ.",
      "وَلَا يَقُلْ أَحَدُكُمْ: عَبْدِي وَأَمَتِي، وَلْيَقُلْ: فَتَايَ وَفَتَاتِي وَغُلَامِي»."
    ]},
    { title: "[٥٥] باب لا يرد من سأل بالله", paras: [
      "#بَابٌ: لَا يُرَدُّ مَنْ سَأَلَ بِاللَّهِ",
      "عَنِ ابْنِ عُمَرَ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَنِ اسْتَعَاذَ بِاللَّهِ فَأَعِيذُوهُ، وَمَنْ سَأَلَ بِاللَّهِ فَأَعْطُوهُ، وَمَنْ دَعَاكُمْ فَأَجِيبُوهُ، وَمَنْ صَنَعَ إِلَيْكُمْ مَعْرُوفاً فَكَافِئُوهُ، فَإِنْ لَمْ تَجِدُوا مَا تُكَافِئُونَهُ؛ فَادْعُوا لَهُ حَتَّى تَرَوْا أَنَّكُمْ قَدْ كَافَأْتُمُوهُ» رَوَاهُ أَبُو دَاوُدَ، وَالنَّسَائِيُّ، بِإِسْنَادٍ صَحِيحٍ."
    ]},
    { title: "[٥٦] باب لا يسأل بوجه الله إلا الجنة", paras: [
      "#بَابٌ: لَا يُسْأَلُ بِوَجْهِ اللَّهِ إِلَّا الْجَنَّةُ",
      "عَنْ جَابِرٍ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا يُسْأَلُ بِوَجْهِ اللَّهِ إِلَّا الْجَنَّةُ» رَوَاهُ أَبُو دَاوُدَ."
    ]},
    { title: "[٥٧] باب ما جاء في اللو", paras: [
      "#بَابُ مَا جَاءَ فِي اللَّوِّ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿يَقُولُونَ لَوْ كَانَ لَنَا مِنَ الأَمْرِ شَيْءٌ مَا قُتِلْنَا هَهُنَا﴾.",
      "وَقَوْلُهُ: ﴿الَّذِينَ قَالُوا لِإِخْوَانِهِمْ وَقَعَدُوا لَوْ أَطَاعُونَا مَا قُتِلُوا﴾ الآيَةَ.",
      "فِي الصَّحِيحِ: عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «احْرِصْ عَلَى مَا يَنْفَعُكَ، وَاسْتَعِنْ بِاللَّهِ، وَلَا تَعْجَزْ.",
      "وَإِنْ أَصَابَكَ شَيْءٌ، فَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ، كَانَ كَذَا وَكَذَا، وَلَكِنْ قُلْ: قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ؛ فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ»."
    ]},
    { title: "[٥٨] باب النهي عن سب الريح", paras: [
      "#بَابُ النَّهْيِ عَنْ سَبِّ الرِّيحِ",
      "عَنْ أُبَيِّ بْنِ كَعْبٍ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «لَا تَسُبُّوا الرِّيحَ، فَإِذَا رَأَيْتُمْ مَا تَكْرَهُونَ؛ فَقُولُوا: اللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ هَذِهِ الرِّيحِ، وَخَيْرِ مَا فِيهَا، وَخَيْرِ مَا أُمِرَتْ بِهِ، وَنَعُوذُ بِكَ مِنْ شَرِّ هَذِهِ الرِّيحِ، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُمِرَتْ بِهِ» صَحَّحَهُ التِّرْمِذِيُّ."
    ]},
    { title: "[٥٩] باب قول الله تعالى: ﴿يظنون بالله غير الحق ظن الجاهلية﴾", paras: [
      "#بَابُ قَوْلِ اللَّهِ تَعَالَى: ﴿يَظُنُّونَ بِاللَّهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِ يَقُولُونَ هَلْ لَنَا مِنَ الأَمْرِ مِنْ شَيْءٍ قُلْ إِنَّ الأَمْرَ كُلَّهُ لِلَّهِ﴾ الآيَةَ",
      "وَقَوْلُهُ: ﴿الظَّانِّينَ بِاللَّهِ ظَنَّ السَّوْءِ عَلَيْهِمْ دَائِرَةُ السَّوْءِ﴾ الآيَةَ.",
      "قَالَ ابْنُ الْقَيِّمِ - فِي الآيَةِ الأُولَى -: «فُسِّرَ هَذَا الظَّنُّ بِأَنَّهُ سُبْحَانَهُ لَا يَنْصُرُ رَسُولَهُ، وَأَنَّ أَمْرَهُ سَيَضْمَحِلُّ، وَفُسِّرَ بِظَنِّهِمْ أَنَّ مَا أَصَابَهُمْ لَمْ يَكُنْ بِقَدَرِ اللَّهِ وَحِكْمَتِهِ.",
      "فَفُسِّرَ بِإِنْكَارِ الْحِكْمَةِ، وَإِنْكَارِ الْقَدَرِ، وَإِنْكَارِ أَنْ يُتِمَّ أَمْرَ رَسُولِهِ، وَأَنْ يُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ، وَهَذَا هُوَ ظَنُّ السَّوْءِ الَّذِي ظَنَّهُ الْمُنَافِقُونَ وَالْمُشْرِكُونَ فِي سُورَةِ الْفَتْحِ.",
      "وَإِنَّمَا كَانَ هَذَا ظَنَّ السَّوْءِ؛ لِأَنَّهُ ظَنُّ غَيْرِ مَا يَلِيقُ بِهِ سُبْحَانَهُ، وَمَا يَلِيقُ بِحِكْمَتِهِ وَحَمْدِهِ، وَوَعْدِهِ الصَّادِقِ.",
      "فَمَنْ ظَنَّ أَنَّهُ يُدِيلُ الْبَاطِلَ عَلَى الْحَقِّ إِدَالَةً مُسْتَقِرَّةً يَضْمَحِلُّ مَعَهَا الْحَقُّ، أَوْ أَنْكَرَ أَنْ يَكُونَ مَا جَرَى بِقَضَائِهِ وَقَدَرِهِ، أَوْ أَنْكَرَ أَنْ يَكُونَ قَدَرُهُ لِحِكْمَةٍ بَالِغَةٍ يَسْتَحِقُّ عَلَيْهَا الْحَمْدَ؛ بَلْ زَعَمَ أَنَّ ذَلِكَ لِمَشِيئَةٍ مُجَرَّدَةٍ؛ فَـ﴿ذَلِكَ ظَنُّ الَّذِينَ كَفَرُوا فَوَيْلٌ لِلَّذِينَ كَفَرُوا مِنَ النَّارِ﴾.",
      "وَأَكْثَرُ النَّاسِ يَظُنُّونَ بِاللَّهِ ظَنَّ السَّوْءِ فِيمَا يَخْتَصُّ بِهِمْ، وَفِيمَا يَفْعَلُهُ بِغَيْرِهِمْ، وَلَا يَسْلَمُ مِنْ ذَلِكَ إِلَّا مَنْ عَرَفَ اللَّهَ وَأَسْمَاءَهُ وَصِفَاتِهِ، وَمُوجِبَ حِكْمَتِهِ وَحَمْدِهِ.",
      "فَلْيَعْتَنِ اللَّبِيبُ النَّاصِحُ لِنَفْسِهِ بِهَذَا، وَلْيَتُبْ إِلَى اللَّهِ، وَيَسْتَغْفِرْهُ مِنْ ظَنِّهِ بِرَبِّهِ ظَنَّ السَّوْءِ.",
      "وَلَوْ فَتَّشْتَ مَنْ فَتَّشْتَ؛ لَرَأَيْتَ عِنْدَهُ تَعَنُّتاً عَلَى الْقَدَرِ وَمَلَامَةً لَهُ، وَأَنَّهُ كَانَ يَنْبَغِي أَنْ يَكُونَ كَذَا وَكَذَا؛ فَمُسْتَقِلٌّ وَمُسْتَكْثِرٌ، وَفَتِّشْ نَفْسَكَ هَلْ أَنْتَ سَالِمٌ؟",
      "فَإِنْ تَنْجُ مِنْهَا تَنْجُ مِنْ ذِي عَظِيمَةٍ ... وَإِلَّا فَإِنِّي لَا إِخَالُكَ نَاجِيَا»."
    ]},
    { title: "[٦٠] باب ما جاء في منكري القدر", paras: [
      "#بَابُ مَا جَاءَ فِي مُنْكِرِي الْقَدَرِ",
      "وَقَالَ ابْنُ عُمَرَ رضي الله عنهما: «وَالَّذِي نَفْسُ ابْنِ عُمَرَ بِيَدِهِ! لَوْ كَانَ لِأَحَدِهِمْ مِثْلُ أُحُدٍ ذَهَباً، ثُمَّ أَنْفَقَهُ فِي سَبِيلِ اللَّهِ؛ مَا قَبِلَهُ اللَّهُ مِنْهُ، حَتَّى يُؤْمِنَ بِالْقَدَرِ، ثُمَّ اسْتَدَلَّ بِقَوْلِ النَّبِيِّ ﷺ: الإِيمَانُ: أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ» رَوَاهُ مُسْلِمٌ.",
      "وَعَنْ عُبَادَةَ بْنِ الصَّامِتِ رضي الله عنه أَنَّهُ قَالَ لِابْنِهِ: «يَا بُنَيَّ! إِنَّكَ لَنْ تَجِدَ طَعْمَ الإِيمَانِ حَتَّى تَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ: الْقَلَمَ، فَقَالَ لَهُ: اكْتُبْ، فَقَالَ: رَبِّ! وَمَاذَا أَكْتُبُ؟ قَالَ: اكْتُبْ مَقَادِيرَ كُلِّ شَيْءٍ حَتَّى تَقُومَ السَّاعَةُ.",
      "يَا بُنَيَّ! سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: مَنْ مَاتَ عَلَى غَيْرِ هَذَا؛ فَلَيْسَ مِنِّي».",
      "وَفِي رِوَايَةٍ لِأَحْمَدَ: «إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ: الْقَلَمَ، ثُمَّ قَالَ: اكْتُبْ، فَجَرَى فِي تِلْكَ السَّاعَةِ بِمَا هُوَ كَائِنٌ إِلَى يَوْمِ الْقِيَامَةِ».",
      "وَفِي رِوَايَةٍ لِابْنِ وَهْبٍ: قَالَ رَسُولُ اللَّهِ ﷺ: «فَمَنْ لَمْ يُؤْمِنْ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ؛ أَحْرَقَهُ اللَّهُ بِالنَّارِ».",
      "وَفِي «الْمُسْنَدِ»، وَ«السُّنَنِ»: عَنِ ابْنِ الدَّيْلَمِيِّ قَالَ: «أَتَيْتُ أُبَيَّ بْنَ كَعْبٍ رضي الله عنه، فَقُلْتُ: فِي نَفْسِي شَيْءٌ مِنَ الْقَدَرِ؛ فَحَدِّثْنِي بِشَيْءٍ، لَعَلَّ اللَّهَ يُذْهِبُهُ مِنْ قَلْبِي، فَقَالَ: لَوْ أَنْفَقْتَ مِثْلَ أُحُدٍ ذَهَباً؛ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ، وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَلَوْ مِتَّ عَلَى غَيْرِ هَذَا؛ لَكُنْتَ مِنْ أَهْلِ النَّارِ.",
      "قَالَ: فَأَتَيْتُ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ، وَحُذَيْفَةَ بْنَ الْيَمَانِ، وَزَيْدَ بْنَ ثَابِتٍ رضي الله عنهم؛ فَكُلُّهُمْ حَدَّثَنِي بِمِثْلِ ذَلِكَ عَنِ النَّبِيِّ ﷺ» حَدِيثٌ صَحِيحٌ، رَوَاهُ الْحَاكِمُ فِي «صَحِيحِهِ»."
    ]},
    { title: "[٦١] باب ما جاء في المصورين", paras: [
      "#بَابُ مَا جَاءَ فِي الْمُصَوِّرِينَ",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «قَالَ اللَّهُ تَعَالَى: وَمَنْ أَظْلَمُ مِمَّنْ ذَهَبَ يَخْلُقُ كَخَلْقِي؛ فَلْيَخْلُقُوا ذَرَّةً، أَوْ لِيَخْلُقُوا حَبَّةً، أَوْ لِيَخْلُقُوا شَعِيرَةً» أَخْرَجَاهُ.",
      "وَلَهُمَا: عَنْ عَائِشَةَ رضي الله عنها أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «أَشَدُّ النَّاسِ عَذَاباً يَوْمَ الْقِيَامَةِ: الَّذِينَ يُضَاهِئُونَ بِخَلْقِ اللَّهِ».",
      "وَلَهُمَا: عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «كُلُّ مُصَوِّرٍ فِي النَّارِ، يُجْعَلُ لَهُ بِكُلِّ صُورَةٍ صَوَّرَهَا نَفْسٌ يُعَذَّبُ بِهَا فِي جَهَنَّمَ».",
      "وَلَهُمَا: عَنْهُ رضي الله عنه مَرْفُوعاً: «مَنْ صَوَّرَ صُورَةً فِي الدُّنْيَا؛ كُلِّفَ أَنْ يَنْفُخَ فِيهَا الرُّوحَ، وَلَيْسَ بِنَافِخٍ».",
      "وَلِمُسْلِمٍ: عَنْ أَبِي الْهَيَّاجِ قَالَ: «قَالَ لِي عَلِيٌّ رضي الله عنه: أَلَا أَبْعَثُكَ عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللَّهِ ﷺ: أَلَّا تَدَعَ صُورَةً إِلَّا طَمَسْتَهَا، وَلَا قَبْراً مُشْرِفاً إِلَّا سَوَّيْتَهُ»."
    ]},
    { title: "[٦٢] باب ما جاء في كثرة الحلف", paras: [
      "#بَابُ مَا جَاءَ فِي كَثْرَةِ الْحَلِفِ",
      "وَقَوْلُ اللَّهِ تَعَالَى: ﴿وَاحْفَظُوا أَيْمَانَكُمْ﴾.",
      "عَنْ أَبِي هُرَيْرَةَ رضي الله عنه قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «الْحَلِفُ مَنْفَقَةٌ لِلسِّلْعَةِ، مَمْحَقَةٌ لِلْكَسْبِ» أَخْرَجَاهُ.",
      "وَعَنْ سَلْمَانَ رضي الله عنه مَرْفُوعاً: «ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلَا يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ: أُشَيْمِطٌ زَانٍ، وَعَائِلٌ مُسْتَكْبِرٌ، وَرَجُلٌ جَعَلَ اللَّهَ بِضَاعَتَهُ؛ لَا يَشْتَرِي إِلَّا بِيَمِينِهِ، وَلَا يَبِيعُ إِلَّا بِيَمِينِهِ» رَوَاهُ الطَّبَرَانِيُّ بِسَنَدٍ صَحِيحٍ.",
      "وَفِي الصَّحِيحِ: عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رضي الله عنهما قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «خَيْرُ أُمَّتِي قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ - قَالَ عِمْرَانُ: فَلَا أَدْرِي أَذَكَرَ بَعْدَ قَرْنِهِ مَرَّتَيْنِ أَوْ ثَلَاثاً؟ -، ثُمَّ إِنَّ بَعْدَكُمْ قَوْماً يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ، وَيَخُونُونَ وَلَا يُؤْتَمَنُونَ، وَيَنْذُرُونَ وَلَا يُوفُونَ، وَيَظْهَرُ فِيهِمُ السِّمَنُ».",
      "وَفِيهِ: عَنِ ابْنِ مَسْعُودٍ رضي الله عنه أَنَّ النَّبِيَّ ﷺ قَالَ: «خَيْرُ النَّاسِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ يَجِيءُ قَوْمٌ تَسْبِقُ شَهَادَةُ أَحَدِهِمْ يَمِينَهُ، وَيَمِينُهُ شَهَادَتَهُ».",
      "قَالَ إِبْرَاهِيمُ: «كَانُوا يَضْرِبُونَنَا عَلَى الشَّهَادَةِ وَالْعَهْدِ، وَنَحْنُ صِغَارٌ»."
    ]},
    { title: "[٦٣] باب ما جاء في ذمة الله وذمة نبيه", paras: [
      "#بَابُ مَا جَاءَ فِي ذِمَّةِ اللَّهِ وَذِمَّةِ نَبِيِّهِ",
      "وَقَوْلُهُ: ﴿وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدْتُمْ وَلَا تَنْقُضُوا الأَيْمَانَ بَعْدَ تَوْكِيدِهَا﴾ الآيَةَ.",
      "عَنْ بُرَيْدَةَ رضي الله عنه: «أَنَّ رَسُولَ اللَّهِ ﷺ كَانَ إِذَا أَمَّرَ أَمِيراً عَلَى جَيْشٍ أَوْ سَرِيَّةٍ؛ أَوْصَاهُ بِتَقْوَى اللَّهِ، وَمَنْ مَعَهُ مِنَ الْمُسْلِمِينَ خَيْراً، ثُمَّ قَالَ: اغْزُوا بِسْمِ اللَّهِ، فِي سَبِيلِ اللَّهِ، قَاتِلُوا مَنْ كَفَرَ بِاللَّهِ، اغْزُوا وَلَا تَغُلُّوا، وَلَا تَغْدِرُوا، وَلَا تُمَثِّلُوا، وَلَا تَقْتُلُوا وَلِيداً.",
      "وَإِذَا لَقِيتَ عَدُوَّكَ مِنَ الْمُشْرِكِينَ؛ فَادْعُهُمْ إِلَى ثَلَاثِ خِصَالٍ - أَوْ خِلَالٍ -، فَأَيَّتَهُنَّ مَا أَجَابُوكَ؛ فَاقْبَلْ مِنْهُمْ، وَكُفَّ عَنْهُمْ.",
      "ثُمَّ ادْعُهُمْ إِلَى الإِسْلَامِ، فَإِنْ أَجَابُوكَ؛ فَاقْبَلْ مِنْهُمْ.",
      "ثُمَّ ادْعُهُمْ إِلَى التَّحَوُّلِ مِنْ دَارِهِمْ إِلَى دَارِ الْمُهَاجِرِينَ، وَأَخْبِرْهُمْ أَنَّهُمْ إِنْ فَعَلُوا ذَلِكَ؛ فَلَهُمْ مَا لِلْمُهَاجِرِينَ، وَعَلَيْهِمْ مَا عَلَى الْمُهَاجِرِينَ.",
      "فَإِنْ أَبَوْا أَنْ يَتَحَوَّلُوا مِنْهَا؛ فَأَخْبِرْهُمْ أَنَّهُمْ يَكُونُونَ كَأَعْرَابِ الْمُسْلِمِينَ، يَجْرِي عَلَيْهِمْ حُكْمُ اللَّهِ تَعَالَى الَّذِي يَجْرِي عَلَى الْمُؤْمِنِينَ، وَلَا يَكُونُ لَهُمْ فِي الْغَنِيمَةِ وَالْفَيْءِ شَيْءٌ؛ إِلَّا أَنْ يُجَاهِدُوا مَعَ الْمُسْلِمِينَ.",
      "فَإِنْ هُمْ أَبَوْا؛ فَاسْأَلْهُمُ الْجِزْيَةَ، فَإِنْ هُمْ أَجَابُوكَ؛ فَاقْبَلْ مِنْهُمْ، وَكُفَّ عَنْهُمْ.",
      "فَإِنْ هُمْ أَبَوْا؛ فَاسْتَعِنْ بِاللَّهِ وَقَاتِلْهُمْ.",
      "وَإِذَا حَاصَرْتَ أَهْلَ حِصْنٍ، فَأَرَادُوكَ أَنْ تَجْعَلَ لَهُمْ ذِمَّةَ اللَّهِ وَذِمَّةَ نَبِيِّهِ؛ فَلَا تَجْعَلْ لَهُمْ ذِمَّةَ اللَّهِ وَلَا ذِمَّةَ نَبِيِّهِ، وَلَكِنِ اجْعَلْ لَهُمْ ذِمَّتَكَ وَذِمَّةَ أَصْحَابِكَ، فَإِنَّكُمْ أَنْ تُخْفِرُوا ذِمَمَكُمْ وَذِمَمَ أَصْحَابِكُمْ، أَهْوَنُ مِنْ أَنْ تُخْفِرُوا ذِمَّةَ اللَّهِ وَذِمَّةَ نَبِيِّهِ.",
      "وَإِذَا حَاصَرْتَ أَهْلَ حِصْنٍ، فَأَرَادُوكَ أَنْ تُنْزِلَهُمْ عَلَى حُكْمِ اللَّهِ؛ فَلَا تُنْزِلْهُمْ عَلَى حُكْمِ اللَّهِ، وَلَكِنْ أَنْزِلْهُمْ عَلَى حُكْمِكَ؛ فَإِنَّكَ لَا تَدْرِي أَتُصِيبُ حُكْمَ اللَّهِ فِيهِمْ، أَمْ لَا» رَوَاهُ مُسْلِمٌ."
    ]},
    { title: "[٦٤] باب ما جاء في الإقسام على الله", paras: [
      "#بَابُ مَا جَاءَ فِي الإِقْسَامِ عَلَى اللَّهِ",
      "عَنْ جُنْدُبِ بْنِ عَبْدِ اللَّهِ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «قَالَ رَجُلٌ: وَاللَّهِ لَا يَغْفِرُ اللَّهُ لِفُلَانٍ، فَقَالَ اللَّهُ عَزَّ وَجَلَّ: مَنْ ذَا الَّذِي يَتَأَلَّى عَلَيَّ أَلَّا أَغْفِرَ لِفُلَانٍ؟! إِنِّي قَدْ غَفَرْتُ لَهُ، وَأَحْبَطْتُ عَمَلَكَ» رَوَاهُ مُسْلِمٌ.",
      "وَفِي حَدِيثِ أَبِي هُرَيْرَةَ رضي الله عنه: «أَنَّ الْقَائِلَ رَجُلٌ عَابِدٌ». قَالَ أَبُو هُرَيْرَةَ: «تَكَلَّمَ بِكَلِمَةٍ أَوْبَقَتْ دُنْيَاهُ وَآخِرَتَهُ»."
    ]},
    { title: "[٦٥] باب لا يستشفع بالله على خلقه", paras: [
      "#بَابٌ: لَا يُسْتَشْفَعُ بِاللَّهِ عَلَى خَلْقِهِ",
      "عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رضي الله عنه قَالَ: «جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ﷺ، فَقَالَ: يَا رَسُولَ اللَّهِ! نُهِكَتِ الأَنْفُسُ، وَجَاعَ الْعِيَالُ، وَهَلَكَتِ الأَمْوَالُ؛ فَاسْتَسْقِ لَنَا رَبَّكَ، فَإِنَّا نَسْتَشْفِعُ بِاللَّهِ عَلَيْكَ، وَبِكَ عَلَى اللَّهِ.",
      "فَقَالَ النَّبِيُّ ﷺ: سُبْحَانَ اللَّهِ! سُبْحَانَ اللَّهِ! فَمَا زَالَ يُسَبِّحُ حَتَّى عُرِفَ ذَلِكَ فِي وُجُوهِ أَصْحَابِهِ، ثُمَّ قَالَ: وَيْحَكَ! أَتَدْرِي مَا اللَّهُ؟ إِنَّ شَأْنَ اللَّهِ أَعْظَمُ مِنْ ذَلِكَ، إِنَّهُ لَا يُسْتَشْفَعُ بِاللَّهِ عَلَى أَحَدٍ...» وَذَكَرَ الْحَدِيثَ. رَوَاهُ أَبُو دَاوُدَ."
    ]},
    { title: "[٦٦] باب حماية النبي ﷺ حمى التوحيد وسده طرق الشرك", paras: [
      "#بَابُ مَا جَاءَ فِي حِمَايَةِ النَّبِيِّ ﷺ حِمَى التَّوْحِيدِ، وَسَدِّهِ طُرُقَ الشِّرْكِ",
      "عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ رضي الله عنه قَالَ: «انْطَلَقْتُ فِي وَفْدِ بَنِي عَامِرٍ إِلَى رَسُولِ اللَّهِ ﷺ، فَقُلْنَا: أَنْتَ سَيِّدُنَا، فَقَالَ: السَّيِّدُ اللَّهُ، قُلْنَا: وَأَفْضَلُنَا فَضْلاً، وَأَعْظَمُنَا طَوْلاً، فَقَالَ: قُولُوا بِقَوْلِكُمْ أَوْ بَعْضِ قَوْلِكُمْ، وَلَا يَسْتَجْرِيَنَّكُمُ الشَّيْطَانُ» رَوَاهُ أَبُو دَاوُدَ بِسَنَدٍ جَيِّدٍ.",
      "وَعَنْ أَنَسٍ رضي الله عنه: «أَنَّ نَاساً قَالُوا: يَا رَسُولَ اللَّهِ! يَا خَيْرَنَا وَابْنَ خَيْرِنَا، وَسَيِّدَنَا وَابْنَ سَيِّدِنَا! فَقَالَ: يَا أَيُّهَا النَّاسُ! قُولُوا بِقَوْلِكُمْ، وَلَا يَسْتَهْوِيَنَّكُمُ الشَّيْطَانُ، أَنَا مُحَمَّدٌ عَبْدُ اللَّهِ وَرَسُولُهُ، مَا أُحِبُّ أَنْ تَرْفَعُونِي فَوْقَ مَنْزِلَتِي الَّتِي أَنْزَلَنِي اللَّهُ عَزَّ وَجَلَّ» رَوَاهُ النَّسَائِيُّ بِسَنَدٍ جَيِّدٍ."
    ]},
    { title: "[٦٧] باب قول الله تعالى: ﴿وما قدروا الله حق قدره﴾", paras: [
      "#بَابُ مَا جَاءَ فِي قَوْلِ اللَّهِ تَعَالَى: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالأَرْضُ جَمِيعاً قَبْضَتُهُ يَوْمَ الْقِيَامَةِ﴾ الآيَةَ",
      "عَنِ ابْنِ مَسْعُودٍ رضي الله عنه قَالَ: «جَاءَ حَبْرٌ مِنَ الأَحْبَارِ إِلَى رَسُولِ اللَّهِ ﷺ، فَقَالَ: يَا مُحَمَّدُ! إِنَّا نَجِدُ أَنَّ اللَّهَ يَجْعَلُ السَّمَاوَاتِ عَلَى إِصْبَعٍ، وَالأَرَضِينَ عَلَى إِصْبَعٍ، وَالشَّجَرَ عَلَى إِصْبَعٍ، وَالْمَاءَ وَالثَّرَى عَلَى إِصْبَعٍ، وَسَائِرَ الْخَلَائِقِ عَلَى إِصْبَعٍ، فَيَقُولُ: أَنَا الْمَلِكُ، فَضَحِكَ رَسُولُ اللَّهِ ﷺ حَتَّى بَدَتْ نَوَاجِذُهُ؛ تَصْدِيقاً لِقَوْلِ الْحَبْرِ، ثُمَّ قَرَأَ: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالأَرْضُ جَمِيعاً قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ﴾ الآيَةَ».",
      "وَفِي رِوَايَةٍ لِمُسْلِمٍ: «وَالْجِبَالَ وَالشَّجَرَ عَلَى إِصْبَعٍ، ثُمَّ يَهُزُّهُنَّ، فَيَقُولُ: أَنَا الْمَلِكُ، أَنَا اللَّهُ».",
      "وَفِي رِوَايَةٍ لِلْبُخَارِيِّ: «يَجْعَلُ السَّمَاوَاتِ عَلَى إِصْبَعٍ، وَالْمَاءَ وَالثَّرَى عَلَى إِصْبَعٍ، وَسَائِرَ الْخَلْقِ عَلَى إِصْبَعٍ» أَخْرَجَاهُ.",
      "وَلِمُسْلِمٍ: عَنِ ابْنِ عُمَرَ رضي الله عنهما مَرْفُوعاً: «يَطْوِي اللَّهُ السَّمَاوَاتِ يَوْمَ الْقِيَامَةِ، ثُمَّ يَأْخُذُهُنَّ بِيَدِهِ الْيُمْنَى، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ، أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟ ثُمَّ يَطْوِي الأَرَضِينَ السَّبْعَ، ثُمَّ يَأْخُذُهُنَّ بِشِمَالِهِ، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ، أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟».",
      "وَرُوِيَ عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ: «مَا السَّمَاوَاتُ السَّبْعُ وَالأَرَضُونَ السَّبْعُ فِي كَفِّ الرَّحْمَنِ؛ إِلَّا كَخَرْدَلَةٍ فِي يَدِ أَحَدِكُمْ».",
      "وَقَالَ ابْنُ جَرِيرٍ: حَدَّثَنِي يُونُسُ، أَخْبَرَنَا ابْنُ وَهْبٍ، قَالَ: قَالَ ابْنُ زَيْدٍ: حَدَّثَنِي أَبِي، قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «مَا السَّمَاوَاتُ السَّبْعُ فِي الْكُرْسِيِّ، إِلَّا كَدَرَاهِمَ سَبْعَةٍ أُلْقِيَتْ فِي تُرْسٍ».",
      "قَالَ: وَقَالَ أَبُو ذَرٍّ رضي الله عنه: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «مَا الْكُرْسِيُّ فِي الْعَرْشِ، إِلَّا كَحَلْقَةٍ مِنْ حَدِيدٍ أُلْقِيَتْ بَيْنَ ظَهْرَيْ فَلَاةٍ مِنَ الأَرْضِ».",
      "وَعَنِ ابْنِ مَسْعُودٍ رضي الله عنه قَالَ: «بَيْنَ السَّمَاءِ الدُّنْيَا وَالَّتِي تَلِيهَا خَمْسُ مِئَةِ عَامٍ، وَبَيْنَ كُلِّ سَمَاءٍ خَمْسُ مِئَةِ عَامٍ، وَبَيْنَ السَّمَاءِ السَّابِعَةِ وَالْكُرْسِيِّ خَمْسُ مِئَةِ عَامٍ، وَبَيْنَ الْكُرْسِيِّ وَالْمَاءِ خَمْسُ مِئَةِ عَامٍ، وَالْعَرْشُ فَوْقَ الْمَاءِ، وَاللَّهُ فَوْقَ الْعَرْشِ، لَا يَخْفَى عَلَيْهِ شَيْءٌ مِنْ أَعْمَالِكُمْ» أَخْرَجَهُ ابْنُ مَهْدِيٍّ: عَنْ حَمَّادِ بْنِ سَلَمَةَ، عَنْ عَاصِمٍ، عَنْ زِرٍّ، عَنْ عَبْدِ اللَّهِ.",
      "وَرَوَاهُ بِنَحْوِهِ الْمَسْعُودِيُّ: عَنْ عَاصِمٍ، عَنْ أَبِي وَائِلٍ، عَنْ عَبْدِ اللَّهِ رضي الله عنه. قَالَهُ الْحَافِظُ الذَّهَبِيُّ، قَالَ: «وَلَهُ طُرُقٌ».",
      "وَعَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رضي الله عنه قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «هَلْ تَدْرُونَ كَمْ بَيْنَ السَّمَاءِ وَالأَرْضِ؟ قُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: بَيْنَهُمَا مَسِيرَةُ خَمْسِ مِئَةِ سَنَةٍ، وَمِنْ كُلِّ سَمَاءٍ إِلَى سَمَاءٍ مَسِيرَةُ خَمْسِ مِئَةِ سَنَةٍ، وَكِثَفُ كُلِّ سَمَاءٍ مَسِيرَةُ خَمْسِ مِئَةِ سَنَةٍ، وَبَيْنَ السَّمَاءِ السَّابِعَةِ وَالْعَرْشِ بَحْرٌ، بَيْنَ أَسْفَلِهِ وَأَعْلَاهُ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، وَاللَّهُ تَعَالَى فَوْقَ ذَلِكَ، لَا يَخْفَى عَلَيْهِ شَيْءٌ مِنْ أَعْمَالِ بَنِي آدَمَ» أَخْرَجَهُ أَبُو دَاوُدَ وَغَيْرُهُ.",
      "وَاللَّهُ سُبْحَانَهُ وَتَعَالَى أَعْلَمُ."
    ]}
  ]
});
